INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('8b2b8d70-d93f-4000-8ef1-357d720fa7c5', 'Glute Bridge March', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'Build stronger glutes with this bridging movement focused on hip extension. Secondary activation of your hamstrings provides additional muscle engagement. No equipment needed—your body provides all the resistance. Strong legs are the foundation for athletic performance and functional fitness. Progress gradually by increasing resistance over time.', '38161201', '38161201-Glute-Bridge-March-(female)_Hips-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum. Works well for glutes activation.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge March', 'hip_thrust, romanian_deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8b3db99b-c2e6-4069-89cd-108cb4f9c532', 'Incline Lying Rear Delt Raise (EZ Bar)', 'Shoulders', 'EZ Bar, Flat Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The EZ Bar Incline Lying Rear Delt Raise is a raising exercise that targets your rear delts for shoulder development. Your upper back work as secondary movers, adding to the training stimulus. Performing this lying down removes momentum for stricter form. Shoulder development enhances both performance and upper body aesthetics.', '96471201', '96471201-EZ-Bar-Incline-Lying-Rear-Delt-Raise_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Lie down in the appropriate position for EZ Bar Incline Lying Rear Delt Raise. 3. Raise your arms out to the sides and back, focusing on rear delts. 4. Lower with control, maintaining tension throughout. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'rear_delt', 'EZ Bar Incline Lying Rear Delt Raise', 'shoulder_press, lateral_raise, face_pull, bent_over_row', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('8b3e31fc-81ed-42f4-b29a-45e6ce6cf7f5', 'Frog Pose With Bolster', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Frog Pose With Bolster provides a deep stretch for your adductors, ideal for recovery and mobility work. You''ll also feel your hips working to support the movement. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '78361201', '78361201-Frog-Pose-with-Bolster-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Move into the stretch position for Frog Pose With Bolster. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'general_exercise', 'Frog Pose With Bolster', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('8b5a5947-6e14-4aeb-a59c-f7d46daf632f', 'Lying Front Raise (Barbell)', 'Shoulders', 'Barbell, Flat Bench', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'Target your front delts with the Barbell Lying Front Raise, an effective shoulder raising exercise. The lying position provides back support and helps isolate the target muscles. The barbell allows you to handle heavier loads for maximum strength gains. Shoulder development enhances both performance and upper body aesthetics.', '105881201', '105881201-Barbell-Lying-Front-Raise-(male)_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:29.36063+00', '1. Grip a barbell with hands at the appropriate width for Barbell Lying Front Raise. 2. Lie down in the appropriate position for Barbell Lying Front Raise. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'front_raise', 'Lying Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('8b5cdc03-ba8e-402e-af82-264d9d7c896d', 'Goblet Walking Lunge (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This lunging movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Dumbbells allow each arm to work independently, helping correct imbalances. Lower body strength improves everything from walking to heavy compound lifts.', '77111201', '77111201-Dumbbell-Goblet-Walking-Lunge_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Goblet Walking Lunge. 2. Step forward into a lunge, then bring your back foot forward for the next step. 3. Push through your front/working leg to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 82, 9, 8, FALSE, TRUE, 'lunge', 'Goblet Walking Lunge', 'split_squat, step_up, squat', TRUE, 'dumbbell', TRUE, 1, 60, 4, 92, 90, 92, 90),
('8b5e67e1-8777-4e90-90f8-e6e31976f2fb', 'Glued Heels Leg Extension (Chair)', 'Legs', 'Chair', '{"Quads"}'::text[], '{}'::text[], 'This extension movement emphasizes your quadriceps for stronger, more powerful legs. Leg training boosts metabolism and builds functional, real-world strength.', '76661201', '76661201-Glued-Heels-Leg-Extension-on-a-Chair-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Extend your legs until straight, squeezing your quads at the top. 3. Lower with control back to the starting position. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_extension', 'Glued Heels Leg Extension On A Chair', 'squat, leg_press, lunge', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8b5e75c8-fd84-4a6a-a66c-840a3c906ae9', 'Rear Fly (Dumbbell)', 'Shoulders', 'Dumbbells, Flat Bench', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'Build stronger shoulders with this flying movement focusing on your rear delts. You''ll also feel your front delts working to support the movement. Using dumbbells requires more stabilization than barbell variations. Shoulder development enhances both performance and upper body aesthetics.', '23921201', '23921201-Dumbbell-Rear-Fly-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rear Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'rear_delt', 'Rear Fly', 'bench_press, incline_bench_press, push_up', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('8b61e4c8-3627-4508-bf6a-ee2e298fa541', 'Kneeling Straight Leg Side Slide (Towel)', 'Core', 'Towel', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Kneeling Straight Leg Side Slide With Towel, focusing on your core. Kneeling helps eliminate lower body momentum from the movement. Building core stability helps with everything from heavy deadlifts to daily activities.', '84991201', '84991201-Kneeling-Straight-Leg-Side-Slide-with-Towel-(femal.mp4', 'female', FALSE, '2025-12-03 23:26:34.487002+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling Straight Leg Side Slide With Towel. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'romanian_deadlift', 'Kneeling Straight Leg Side Slide With Towel', 'deadlift, leg_curl, hip_thrust', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8b622b6e-66b8-4418-afda-fb604231cbde', 'Lying Incline Single Leg Kickback (Cable)', 'Legs', 'Cables', '{"Glutes"}'::text[], '{"Rear Delts"}'::text[], 'Develop your posterior chain with this kicking movement that emphasizes the glutes. The hamstrings assist throughout the movement, making this a well-rounded exercise. Performing this lying down removes momentum for stricter form. The cable setup allows you to adjust the angle of resistance. Strong legs are the foundation for athletic performance and functional fitness.', '99281201', '99281201-Cable-Lying-Incline-Single-Leg-Kickback-(female)_H.mp4', 'female', FALSE, '2025-12-03 23:26:31.931873+00', '1. Adjust the cable machine to the correct height and attachment for Cable Lying Incline Single Leg Kickback. 2. Lie down in the appropriate position for Cable Lying Incline Single Leg Kickback. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Complete all reps on one side, then switch to the other side. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 58, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Lying Incline Single Leg Kickback', 'squat, lunge, leg_press', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('8b715802-b8c2-42de-b249-b1addae3086c', 'Side Step Deep Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity squatting exercise that challenges your entire body. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Plyometric training builds explosive power that transfers to sports and daily activities.', '69241201', '69241201-Side-Step-Deep-Squat-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.203368+00', '1. Set up a box or step platform at the appropriate height. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Repeat for the prescribed number of repetitions. Don''t rush—quality over quantity.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Side Step Deep Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8b71873c-3946-4da8-9de1-f69814fbf30e', 'Assisted Chin Up On A Bench (Pull-Up Bar)', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This movement exercise emphasizes your lats for improved back development. Your biceps work as secondary movers, adding to the training stimulus. Back development is crucial for pulling strength and overall upper body function. Keep your core engaged throughout the exercise.', '64881201', '64881201-Assisted-Chin-Up-on-a-bench-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Pull yourself up, focusing on bicep and lat engagement. 2. Raise until chin is over the bar, lower with full control. 3. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Assisted Chin Up On A Bench', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8b7d45e2-3850-4c59-a303-d57c7883bbd8', 'Elevated Heel Clean Grip Squat (Barbell)', 'Legs', 'Barbell, Step Platform', '{"Quads","Glutes"}'::text[], '{}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. Leg training boosts metabolism and builds functional, real-world strength. Focus on controlled form throughout each repetition.', '95161201', '95161201-Barbell-Elevated-Heel-Clean-Grip-Squat_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Set up a barbell in a rack at the appropriate height for Barbell Elevated Heel Clean Grip Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 3, 6, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'squat', 'Elevated Heel Clean Grip Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'barbell', FALSE, 4, 120, 6, 95, 80, 65, 95),
('8b8a5716-13e4-4bf8-8bba-ee7ca738f450', 'Lying Triceps Extension - Skull Crusher (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'This extension movement isolates your triceps for improved arm development. The lying position provides back support and helps isolate the target muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '104321201', '104321201-Dumbbell-Lying-Triceps-Extension-Skull-Crusher-(V.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Lying Triceps Extension Skull Crusher (V. 2. Lie down in the appropriate position for Dumbbell Lying Triceps Extension Skull Crusher (V. 3. Extend at the elbow until your arm is straight, squeezing the tricep. 4. Lower with control, keeping your upper arm stationary. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 74, 5, 7, FALSE, TRUE, 'tricep_extension', 'Lying Triceps Extension Skull Crusher', 'tricep_pushdown, close_grip_bench', FALSE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('8b999b52-f5f1-4780-a659-a2db10a2b9c7', 'Reverse Vertical Hack Squat (Machine)', 'Legs', 'Hack Squat Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. You''ll also feel your glutes working to support the movement. Machine exercises are great for isolating muscles and training to failure safely. Strong legs are the foundation for athletic performance and functional fitness.', '55161201', '55161201-Lever-Reverse-Vertical-Hack-Squat_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.991486+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Reverse Vertical Hack Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout. Engage your stabilizer muscles for better control.', 'Squat', NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 93, 7, 9, TRUE, FALSE, 'hack_squat', 'Lever Reverse Vertical Hack Squat', 'leg_press, squat, leg_extension', TRUE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('8b9b7499-d497-4058-933a-25108366cc62', 'Standing Knee Raise - Alternating', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Standing Alternate Knee Raise builds reactive power and improves conditioning. Secondary activation of your hip flexors provides additional muscle engagement. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '85601201', '85601201-Standing-Alternate-Knee-Raise-(female)_Plyometrics.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand tall with your feet firmly planted. 2. Raise the weight in the prescribed direction for Standing Alternate Knee Raise. 3. Lower with control, maintaining tension throughout. 4. Alternate between sides/arms/legs with each repetition. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'leg_raise', 'Standing Knee Raise - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8ba3bc22-96b6-482b-969b-ec030443a4c0', 'Seated Forward Bend Yoga Pose', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Seated Forward Bend Yoga Pose provides a deep stretch for your hamstrings, ideal for recovery and mobility work. Secondary activation of your lower back provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Flexibility work like this enhances performance and prevents stiffness.', '52531201', '52531201-Seated-Forward-Bend-Yoga-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Forward Bend Yoga Pose. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Seated Forward Bend Yoga Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('8ba9430d-c22c-42fc-9349-ae072786f860', 'Rear Drive (Cable)', 'Shoulders', 'Cables', '{"Rear Delts"}'::text[], '{"Upper Back","Traps"}'::text[], 'The Cable Rear Drive is an arm movement exercise targeting your rear delts. You''ll also feel your triceps working to support the movement. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '2041201', '02041201-Cable-Rear-Drive_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Rear Drive. 2. Set up in the starting position for Cable Rear Drive. 3. Execute the movement with proper form, focusing on your rear delts. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'general_exercise', 'Rear Drive', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('8bb8652d-6048-4d32-8a93-18e59dfa5d6d', 'Lateral Walk (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{}'::text[], 'Build leg strength with this stepping movement focusing on your full body. Resistance bands provide accommodating resistance that increases through the range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '24601201', '24601201-Resistance-Band-Lateral-Walk-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Lateral Walk. 2. Set up in the starting position for Resistance Band Lateral Walk. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'walking', 'Lateral Walk', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('8bb9354b-fb33-4444-9ac4-caf45a458e50', 'Wrist Curl (Kettlebell)', 'Arms', 'Kettlebell', '{"Forearms"}'::text[], '{}'::text[], 'The Kettlebell Wrist Curl strengthens your forearms and grip through a curling motion. The forearms assist throughout the movement, making this a well-rounded exercise. Kettlebells are excellent for building functional, real-world strength. Arm strength supports grip, pulling, and pushing in compound movements.', '58621201', '58621201-Kettlebell-Wrist-Curl_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Select an appropriately weighted kettlebell for Kettlebell Wrist Curl. 2. Keep your elbows in a fixed position throughout the movement. 3. Curl the weight up by contracting your biceps, squeezing at the top. 4. Lower with control, resisting the weight on the way down. 5. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'wrist_curl', 'Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('8bc12f01-f95b-4727-b281-6cf86168b8a2', 'Hammer Curl Rope (Cable)', 'Arms', 'Cables', '{"Biceps"}'::text[], '{"Forearms"}'::text[], 'This curling exercise focuses on your biceps for improved arm size and strength. You''ll also feel your forearms working to support the movement. Cables provide constant tension throughout the full range of motion. Arm strength supports grip, pulling, and pushing in compound movements.', '1651201', '01651201-Cable-Hammer-Curl-(with-rope)-(male)_Forearms_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Adjust the cable machine to the correct height and attachment for Cable Hammer Curl. 2. Use a hammer/neutral grip with palms facing each other throughout. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Complete all reps with control before resting.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'hammer_curl', 'Hammer Curl', 'bicep_curl, preacher_curl', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('8bc4e700-4395-42d6-b261-bc51203a73c1', 'Banded Single Leg Hip Thrust (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build stronger glutes with this thrusting movement focused on hip extension. The hamstrings assist throughout the movement, making this a well-rounded exercise. The dumbbell variation provides freedom of movement and greater range of motion. Strong legs are the foundation for athletic performance and functional fitness.', '104001201', '104001201-Dumbbell-Banded-Single-Leg-Hip-Thrust_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Complete all reps on one side, then switch to the other side. 6. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'hip_thrust', 'Banded Single Leg Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('8bd927ef-a701-4f43-8c79-6431cfd8038d', 'Twist Up Down (Cable)', 'Core', 'Cables', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Work your side abdominals with this twisting exercise that strengthens your obliques. Your abs work as secondary movers, adding to the training stimulus. Cable resistance creates smooth, continuous muscle engagement. Core strength is foundational for athletic performance and injury prevention.', '12081201', '12081201-Cable-twist-(up-down)-version-2-(female)_waist.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Adjust the cable machine to the correct height and attachment for Cable Twist. 2. Rotate your torso through the movement pattern for Cable Twist. 3. Control the rotation in both directions—avoid using momentum. 4. Repeat for the prescribed number of repetitions. Control the movement—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'russian_twist', 'Twist', 'plank, crunch, leg_raise', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('8be3e330-5b42-4b97-b345-0378a0b5aa84', 'Weighted Counterbalanced Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness. Start with lighter weight to master the movement pattern.', '41281201', '41281201-Weighted-Counterbalanced-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Continue for your target rep count, maintaining good form throughout. Don''t rush—quality over quantity.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'balance', 'Weighted Counterbalanced Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8bf008b0-9fd3-485d-bb0f-ab0f946507ed', 'Assisted Sit Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. You''ll also feel your hip flexors working to support the movement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '80991201', '80991201-Assisted-Sit-Up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Set up in the starting position for Assisted Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Assisted Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8c005372-aee0-4372-8dd5-588c8fe3e883', 'Push Up - Close Grip', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Close Grip Push Up targets your triceps through a pushing motion. Secondary activation of your chest, front delts provides additional muscle engagement. No equipment needed—your body provides all the resistance. Dedicated arm training builds both strength and muscular definition. This is a great exercise for all fitness levels with proper scaling.', '2591201', '02591201-Close-Grip-Push-up_Upper-Arms-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:29.083517+00', '1. Use a close/narrow grip (hands closer than shoulder-width). 2. Keep your body in a straight line from head to heels throughout. 3. Lower your chest toward the floor by bending your elbows. 4. Push through your palms to return to the starting position. 5. Repeat for the prescribed number of repetitions. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Push Up - Close Grip', 'Push Up - Close Grip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8c0ab28a-6b16-4d69-a302-ca239cfa2409', 'Squat Mobilization', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Squat Mobilization provides a deep stretch for your quads, ideal for recovery and mobility work. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Flexibility work like this enhances performance and prevents stiffness.', '105511201', '105511201-Squat-Mobilization-(male)_Stretching_.mp4', 'male', FALSE, '2025-12-03 23:26:26.146796+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Ensure full range of motion on each rep.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 73, 2, 6, FALSE, TRUE, 'mobility', 'Squat Mobilization', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('8c0dc5a3-333d-4c47-acd7-ee85d3510e0a', 'High Plank To Frog Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Target the front of your thighs with this squatting exercise for quad development. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '103641201', '103641201-High-Plank-to-Frog-Squat-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.87243+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Keep your core engaged for stability.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'High Plank To Frog Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('8c155ccf-a1c6-4444-98e4-8bca71ef8a97', 'Seated Twist (Machine)', 'Core', 'Ab Machine', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build rotational power and define your waistline with the Lever Seated Twist. Your abs work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. The fixed path allows you to focus purely on muscular effort. Building core stability helps with everything from heavy deadlifts to daily activities.', '24441201', '24441201-Lever-Seated-Twist-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Twist. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Rotate your torso through the movement pattern for Lever Seated Twist. 4. Control the rotation in both directions—avoid using momentum. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, FALSE, NULL, 'Strength', 60, 5, 7, FALSE, TRUE, 'russian_twist', 'Lever Seated Twist', 'squat, bench_press, deadlift', FALSE, 'machine', FALSE, 3, 60, 2, 80, 75, 20, 88),
('8c1a68c2-4e11-4df1-a53b-8e733c0944ae', 'Front Plank To Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pushing exercise engages your chest for improved core stability and strength. Your triceps, front delts work as secondary movers, adding to the training stimulus. No equipment needed—your body provides all the resistance. A strong core improves posture, protects your spine, and enhances all other lifts.', '28901201', '28901201-Front-Plank-to-Push-up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement. This variation specifically emphasizes the chest.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Front Plank To Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8c2da258-cba7-49bb-9db7-1857ed9778e5', 'Circles Knee Stretch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted stretching exercise. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts. Control the negative portion for maximum muscle engagement.', '42781201', '42781201-Circles-Knee-Stretch-(female)_Calves.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Set up in the starting position for Circles Knee Stretch. 2. Execute the movement with proper form, focusing on your calves. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout. Focus on squeezing the target muscle at peak contraction.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'knee_stretch', 'Circles Knee Stretch', 'stretch_hip, stretch_back, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('8c35122a-a3a3-442b-9a6b-91ca6bad17b1', 'Bent Over External Rotation (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Rotator Cuff"}'::text[], '{"Shoulders"}'::text[], 'The Dumbbell Bent Over External Rotation is a rotation exercise that develops back strength and muscle. Bending over allows gravity to provide resistance in a different plane. The dumbbell variation provides freedom of movement and greater range of motion. Back development is crucial for pulling strength and overall upper body function.', '98171201', '98171201-Dumbbell-Bent-Over-External-Rotation-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Bent Over External Rotation. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Rotate your torso through the movement pattern for Dumbbell Bent Over External Rotation. 4. Control the rotation in both directions—avoid using momentum. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 62, 7, 8, TRUE, TRUE, 'external_rotation', 'Bent Over External Rotation', 'squat, bench_press, deadlift', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('8c3d7f54-63e9-43b0-8ac5-7eafbc3ff196', 'Rotational Bench Press (Dumbbell)', 'Chest', 'Dumbbells, Flat Bench', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Dumbbell Rotational Bench Press, an effective pressing movement for upper body strength. Secondary activation of your triceps, front delts provides additional muscle engagement. Dumbbells allow each arm to work independently, helping correct imbalances. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '105731201', '105731201-Dumbbell-Rotational-Bench-Press_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Rotational Bench Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 89, 7, 8, TRUE, TRUE, 'bench_press', 'Rotational Bench Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('8c46069a-f612-4bdd-b1a3-704a120b2a27', 'Incline Prone Row (Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'The Lever Incline Prone Row is a rowing exercise that builds thickness in your upper back. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The lying position provides back support and helps isolate the target muscles. The fixed path allows you to focus purely on muscular effort. Back development is crucial for pulling strength and overall upper body function.', '106461201', '106461201-Lever-Incline-Prone-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:29.837118+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Incline Prone Row. 2. Lie face down (prone position) for Lever Incline Prone Row. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 81, 7, 9, TRUE, FALSE, 'general_exercise', 'Lever Incline Prone Row', 'squat, bench_press, deadlift', TRUE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('8c4a06aa-c636-4136-9301-814ef0bccadf', 'Ring Leg Curl With Yoga Block And Towel (Gymnastic Rings)', 'Legs', 'Gymnastic Rings, Towel, Yoga Block', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Secondary activation of your calves provides additional muscle engagement. Strong legs are the foundation for athletic performance and functional fitness.', '78701201', '78701201-Ring-Leg-Curl-with-yoga-block-and-towel_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.67144+00', '1. Curl your heels toward your glutes by bending at the knees. 2. Squeeze your hamstrings at peak contraction. 3. Extend legs back out with control. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'leg_curl', 'Ring Leg Curl With Yoga Block And Towel', 'romanian_deadlift, hip_thrust', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('8c4f3f15-2370-468d-81b8-c83152211b09', 'Seated Floor Crunch Knee Raise And T - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build a stronger core with the Seated Floor Alternating Crunch Knee Raise And T, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '104241201', '104241201-Sitting-Floor-Alternating-Crunch-Knee-Raise-and-T.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Position yourself on the floor for Seated Floor Alternating Crunch Knee Raise And T. 2. Sit on the floor with your legs positioned as required. 3. Raise the weight in the prescribed direction for Seated Floor Alternating Crunch Knee Raise And T. 4. Lower with control, maintaining tension throughout. 5. Alternate between sides/arms/legs with each repetition. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 65, 5, 7, FALSE, TRUE, 'leg_raise', 'Seated Floor Crunch Knee Raise And T - Alternating', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8c593100-1440-4b5e-993b-7a86a81e50af', 'Side Seated Inner Thigh Tap', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build leg strength with this movement movement focusing on your adductors. The seated position helps isolate the target muscles by removing momentum. Strong legs are the foundation for athletic performance and functional fitness. Excellent for pre-exhausting the target muscle before compound lifts.', '81131201', '81131201-Side-Sitting-Inner-Thigh-Tap-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Side Seated Inner Thigh Tap. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_adduction', 'Side Seated Inner Thigh Tap', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8c6538f5-87e9-4987-ab7b-98a18bc378f8', 'Seated Side Step Row (Chair)', 'Back', 'Chair', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This dynamic rowing movement gets your heart rate up while developing explosive strength. Secondary activation of your quads provides additional muscle engagement. Being seated provides stability, allowing you to focus on the working muscles. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '72621201', '72621201-Sitting-Side-Step-Row-on-Chair-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Set up a box or step platform at the appropriate height. 3. Sit with your back supported, core engaged, feet flat on the floor. 4. Pull the weight toward your torso, leading with your elbow(s). 5. Squeeze your shoulder blades together at the peak contraction. 6. Extend back out with control, feeling the stretch in your back. 7. Continue for your target rep count, maintaining good form throughout. Maintain a neutral spine throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 55, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Side Step Row On Chair', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8c6eadad-a121-4413-b6b4-972fc8d7b1ce', 'Running Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Running Plank is an explosive exercise that combines cardiovascular training with dynamic stabilization movements. Secondary activation of your shoulders, lower back provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '69811201', '69811201-Running-Plank-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.452942+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 70, 9, 8, FALSE, TRUE, 'running', 'Running Plank', 'crunch, leg_raise, russian_twist, dead_bug', TRUE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('8c7b3bf1-c87d-47e7-aa7b-fa8b1e0788c5', 'Seated Neck Rotation', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your neck with this rotation exercise for improved stability. The seated position helps isolate the target muscles by removing momentum. Include this exercise in your routine for balanced strength development.', '80511201', '80511201-Seated-Neck-Rotation-(female)_Neck_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Neck Rotation. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'neck_stretch', 'Seated Neck Rotation', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8c7bd246-69b5-4d34-8f10-43f053db5c3e', 'Reverse Air Cycling (Stationary Bike)', 'Core', 'Stationary Bike', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities. Perfect for including in both strength and hypertrophy programs.', '78501201', '78501201-Reverse-Air-Cycling-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.417605+00', '1. Set up in the starting position for Reverse Air Cycling. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'cycling', 'Reverse Air Cycling', 'running, elliptical, rowing_cardio', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('8c7f3fd5-d7b0-40a9-9a38-2b1702469a56', 'Tip Toe Knees - Alternating', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Elevate your training with this movement exercise that develops speed, power, and coordination. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning. Aim for full range of motion on every rep.', '61351201', '61351201-Alternating-Tip-Toe-Knees-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:30.54809+00', '1. Alternate between sides/arms/legs with each repetition. 2. Set up in the starting position for Alternating Tip Toe Knees. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'calf_raise', 'Tip Toe Knees - Alternating', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8c8ea539-76ce-4814-aaca-3c1f8d8ff41d', 'Seated High Row V Bar (Cable)', 'Back', 'Cables', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Target your rhomboids and mid-traps with this rowing movement. You''ll also feel your biceps, rear delts working to support the movement. Being seated provides stability, allowing you to focus on the working muscles. Cables provide constant tension throughout the full range of motion. Back development is crucial for pulling strength and overall upper body function.', '30631201', '30631201-Cable-Seated-High-Row-(V-bar)-(female)_Back.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Set the cable pulley to the highest position and attach your preferred handle. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'cable_row', 'Seated High Row', 'bent_over_row, lat_pulldown, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('8c936710-db75-469e-a471-4c1d7b973bd2', 'Lying Hip Extension - Alternating', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Lying Alternate Hip Extension is a hip-dominant extension exercise that targets your glutes. You''ll also feel your hamstrings working to support the movement. The lying position provides back support and helps isolate the target muscles. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '58111201', '58111201-Lying-Alternate-Hip-Extension-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Lie down in the appropriate position for Lying Alternate Hip Extension. 2. Extend through the target joint(s) for Lying Alternate Hip Extension. 3. Alternate between sides/arms/legs with each repetition. 4. Complete all reps with control before resting. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'glute_kickback', 'Lying Hip Extension - Alternating', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8ca04c25-cf48-4a24-8101-525bff4ed6b8', 'Kneeling Chest Press (Resistance Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. Secondary activation of your triceps, front delts provides additional muscle engagement. Kneeling helps eliminate lower body momentum from the movement. Bands are joint-friendly and portable, perfect for any training environment. A well-developed chest contributes to upper body strength and aesthetics.', '86071201', '86071201-Resistance-Band-Kneeling-Chest-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Secure the resistance band appropriately for Resistance Band Kneeling Chest Press. 2. Kneel on the floor (use a pad for comfort if needed). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'bench_press', 'Kneeling Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('8ca309f1-314c-4658-a72c-7c071c6bfc2e', 'Punch March', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '73181201', '73181201-Punch-March-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Set up in the starting position for Punch March. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'marching', 'Punch March', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8ca7e8e2-6cbd-4365-8d3c-e8b8de881a32', 'Standing Pass Around (Resistance Band)', 'Full Body', 'Resistance Band', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with the Resistance Band Standing Pass Around, an effective shoulder movement exercise. Performing this standing challenges your balance and core engagement. Resistance bands provide accommodating resistance that increases through the range of motion. Strong shoulders improve overhead strength and support nearly all upper body movements.', '97591201', '97591201-Resistance-Band-Standing-Pass-Around-(female)_Shou.mp4', 'female', FALSE, '2025-12-03 23:26:36.266593+00', '1. Secure the resistance band appropriately for Resistance Band Standing Pass Around. 2. Stand tall with your feet firmly planted. 3. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 57, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Pass Around', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('8cb6d615-6080-4273-a009-5b8604cb971e', 'Kneeling Adductor Backward Stretch', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'The Kneeling Adductor Backward Stretch is a lower body stretching exercise that targets your adductors. The kneeling position adds a core stability challenge. No equipment needed—your body provides all the resistance. Lower body strength improves everything from walking to heavy compound lifts.', '67091201', '67091201-Kneeling-Adductor-Backward-Stretch-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:25.341124+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Set up in the starting position for Kneeling Adductor Backward Stretch. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'hip_adduction', 'Kneeling Adductor Backward Stretch', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('8cb8cf0a-0609-4f7d-bd59-9aee70c72013', 'Plank Anti Gravity Pull Up (Pull-Up Bar) - Alternating', 'Back', 'Pull-Up Bar', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'The Plank Alternate Anti Gravity Pull Up is a core pulling exercise that primarily targets your lats. Your biceps, upper back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '68041201', '68041201-Plank-Alternate-Anti-Gravity-Pull-up_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Pull yourself up by driving your elbows down and back. 2. Continue until your chin clears the bar, then lower with control to a full hang. 3. Alternate between sides/arms/legs with each repetition. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'pull_up', 'Plank Anti Gravity Pull Up - Alternating', 'lat_pulldown, bent_over_row, bicep_curl', TRUE, 'pull_up_bar', TRUE, 3, 90, 4, 70, 88, 95, 65),
('8cc7acd5-0682-433f-80e1-e5e64b206456', 'Lying Hip Flexion With Knee Bent', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this flexion movement focusing on your core. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '72981201', '72981201-Lying-Hip-Flexion-with-Knee-Bent-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:35.250398+00', '1. Lie down in the appropriate position for Lying Hip Flexion With Knee Bent. 2. Set up in the starting position for Lying Hip Flexion With Knee Bent. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_exercise', 'Lying Hip Flexion With Knee Bent', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8cca5ad2-c87b-4a92-9545-be614971f3da', 'Standing Shoulder Inferior Capsule Stretch', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Designed to lengthen your shoulders, the Standing Shoulder Inferior Capsule Stretch helps improve mobility and prevent stiffness. The upper back assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. Include this in your routine for better mobility and reduced muscle tension.', '80641201', '80641201-Standing-Shoulder-Inferior-Capsule-Stretch-(male)_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Stand tall with your feet firmly planted. 2. Move into the stretch position for Standing Shoulder Inferior Capsule Stretch. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Standing', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 42, 2, 6, FALSE, TRUE, 'stretch_general', 'Standing Shoulder Inferior Capsule Stretch', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('8ccebbfd-3101-4dd8-b9d3-11c9660d567b', 'Low Chest Press (Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. You''ll also feel your triceps, front delts working to support the movement. Bands are joint-friendly and portable, perfect for any training environment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '70331201', '70331201-Band-Low-Chest-Press-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:30.887491+00', '1. Secure the resistance band appropriately for Band Low Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'bench_press', 'Low Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('8cd9c92f-2f3b-4f43-8e7b-f40feac7f6b3', 'Weighted Overhead Crunch (Stability Ball)', 'Core', 'Stability Ball', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Weighted Overhead Crunch (on Stability Ball) is a core crunching exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. The stability ball adds an instability challenge that activates more stabilizer muscles. Building core stability helps with everything from heavy deadlifts to daily activities.', '8401201', '08401201-Weighted-Overhead-Crunch-(on-stability-ball)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Position the stability ball as needed for Weighted Overhead Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'crunch', 'Weighted Overhead Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'stability_ball', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8cdfae5d-ab76-479f-93d4-a1374ded9977', 'Single Leg Squat (Barbell)', 'Legs', 'Barbell', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Barbell One Leg Squat is a squatting exercise that primarily loads your quadriceps. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Using a barbell provides stability for progressive overload. Leg training boosts metabolism and builds functional, real-world strength.', '681201', '00681201-Barbell-One-Leg-Squat_Thighs-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Set up a barbell in a rack at the appropriate height for Barbell One Leg Squat. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 92, 7, 9, TRUE, FALSE, 'pistol_squat', 'Single Leg Squat', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', TRUE, 'barbell', FALSE, 4, 120, 5, 95, 80, 65, 95),
('8ce35e0e-dbe4-4c1e-8059-5f98e2dfdadb', 'Side Lying Hip Adduction (left)', 'Legs', 'Bodyweight', '{"Inner Thighs"}'::text[], '{}'::text[], 'Build leg strength with this movement movement focusing on your adductors. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Lower body strength improves everything from walking to heavy compound lifts.', '59991201', '59991201-Side-Lying-Hip-Adduction-(left)-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying Hip Adduction. 3. Execute the movement with proper form, focusing on your adductors. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hip_adduction', 'Side Lying Hip Adduction', 'hip_abduction, squat, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8ce61050-d79b-4b9e-8c0b-284560a2b648', 'Standing Side Leg Lift Jack', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'The Standing Side Leg Lift Jack is an explosive exercise that combines cardiovascular training with dynamic movement movements. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '89261201', '89261201-Standing-Side-Leg-Lift-Jack-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Side Leg Lift Jack. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 52, 9, 8, TRUE, TRUE, 'leg_exercise', 'Standing Side Leg Lift Jack', 'crunch, plank, russian_twist, hanging_knee_raise', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('8ce7e5c4-25eb-46af-959b-4a96ff2cf2ba', 'Standing 4x Back Criss Cross 4x Front Criss Cross', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Develop functional strength with the Standing 4x Back Criss Cross 4x Front Criss Cross, a comprehensive movement exercise. Performing this standing challenges your balance and core engagement. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength.', '94211201', '94211201-Standing-4x-Back-Criss-Cross-4x-Front-Criss-Cross-.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing 4x Back Criss Cross 4x Front Criss Cross. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'boxing', 'Standing 4x Back Criss Cross 4x Front Criss Cross', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8ce91582-9b1d-4d2a-a203-0752816c5833', 'Seated Press (Dumbbell) - Alternating', 'Shoulders', 'Dumbbells, Flat Bench', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'Target your delts with the Dumbbell Seated Alternate Press, an effective shoulder pressing exercise. Being seated provides stability, allowing you to focus on the working muscles. Using dumbbells requires more stabilization than barbell variations. Strong shoulders improve overhead strength and support nearly all upper body movements.', '25941201', '25941201-Dumbbell-Seated-Alternate-Press-(female)_Shoulders.mp4', 'female', FALSE, '2025-12-03 23:26:33.034396+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Alternate Press. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Start with the weight at shoulder level. 4. Press directly overhead until your arms are fully extended. 5. Lower back to shoulder level with control. 6. Alternate between sides/arms/legs with each repetition. 7. Continue for your target rep count, maintaining good form throughout. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 84, 7, 8, TRUE, TRUE, 'shoulder_press', 'Seated Press - Alternating', 'lateral_raise, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('8cee1dc9-9ff4-467b-9020-67c2589e6232', 'Standing Close Press (Cable)', 'Full Body', 'Cables', '{"Full Body"}'::text[], '{}'::text[], 'The Cable Standing Close Press is an arm pressing exercise targeting your full body. Performing this standing challenges your balance and core engagement. The cable setup allows you to adjust the angle of resistance. Arm strength supports grip, pulling, and pushing in compound movements.', '97451201', '97451201-Cable-Standing-Close-Press-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:32.054831+00', '1. Adjust the cable machine to the correct height and attachment for Cable Standing Close Press. 2. Stand with feet about shoulder-width apart. 3. Execute the pressing motion for Cable Standing Close Press, extending through the target muscles. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Close Press', 'lateral_raise, front_raise, rear_delt_fly, upright_row', FALSE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('8cf29b51-c0b7-4267-a4e1-da1c3b3d92af', 'Seated Hamstring Kick Out (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'This stretch specifically works on your hamstrings, promoting flexibility and reducing muscle tightness. You''ll also feel your lower back working to support the movement. The seated position helps isolate the target muscles by removing momentum. Flexibility work like this enhances performance and prevents stiffness.', '83831201', '83831201-Seated-Hamstring-Kick-Out-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Hamstring Kick Out. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 40, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Hamstring Kick Out', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'gymnastic_rings', FALSE, 3, 90, 4, 68, 85, 85, 70),
('8cf4d342-a5ee-4e1e-9262-2883ea0d6962', 'Plank From Knees', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'The Plank From Knees is a core stabilization exercise that primarily targets your abs. The shoulders, lower back assist throughout the movement, making this a well-rounded exercise. A versatile bodyweight movement perfect for home or gym training. Building core stability helps with everything from heavy deadlifts to daily activities.', '96691201', '96691201-Plank-from-Knees-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:28.71819+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep the movement smooth and controlled. An effective movement for your core routine.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'plank', 'Plank From Knees', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('8d0c6216-f37e-415e-9630-4a303b625451', 'Squat To Leg Extension (Machine)', 'Legs', 'Leg Extension Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness. This is a great exercise for all fitness levels with proper scaling.', '77691201', '77691201-Squat-to-Leg-Extension-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Maintain a neutral spine throughout. This variation specifically emphasizes the quads. Variation: Squat To Leg Extension.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, FALSE, NULL, 'Strength', 100, 7, 9, TRUE, FALSE, 'leg_extension', 'Squat To Leg Extension', 'squat, leg_press, lunge', FALSE, 'machine', FALSE, 4, 120, 5, 80, 75, 20, 88),
('8d18bc9e-5cac-4dc7-870f-3fd9ad06da9d', 'Side Hip Raise (Wall Supported)', 'Legs', 'Wall', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Develop your posterior chain with this raising movement that emphasizes the glutes. Strong legs are the foundation for athletic performance and functional fitness.', '99101201', '99101201-Side-Hip-Raise-Wall-Supported-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:36.985772+00', '1. Position yourself at the appropriate distance from a wall. 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'glute_exercise', 'Side Hip Raise Wall Supported', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8d18e950-ca2e-4783-9a6b-df99278378a6', 'Knee Tuck Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger core with the Knee Tuck Push Up, focusing on your abs. You''ll also feel your triceps, front delts working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Core strength is foundational for athletic performance and injury prevention.', '88941201', '88941201-Knee-Tuck-Push-Up-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:34.322534+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Maintain a neutral spine throughout. Beneficial for overall core development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Knee Tuck Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8d2e08d0-a3c4-4f8c-9c3d-f47a4e18831b', 'Seated Floor Tibialis Press (Resistance Band)', 'Legs', 'Resistance Band', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted pressing exercise. The seated position helps isolate the target muscles by removing momentum. The band creates increasing tension as it stretches, challenging the lockout. Leg training boosts metabolism and builds functional, real-world strength.', '103661201', '103661201-Resistance-Band-Sitting-Floor-Tibialis-Press_Calv.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Secure the resistance band appropriately for Resistance Band Seated Floor Tibialis Press. 2. Position yourself on the floor for Resistance Band Seated Floor Tibialis Press. 3. Sit on the floor with your legs positioned as required. 4. Execute the pressing motion for Resistance Band Seated Floor Tibialis Press, extending through the target muscles. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Floor Tibialis Press', 'squat, bench_press, deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('8d616c48-aaa8-4877-90eb-fbcd472e4ecf', 'Bent Over Single Arm Kickback (Band)', 'Arms', 'Resistance Band', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This kicking movement isolates your triceps for improved arm development. Secondary activation of your hamstrings provides additional muscle engagement. Bending over allows gravity to provide resistance in a different plane. Bands are joint-friendly and portable, perfect for any training environment. Dedicated arm training builds both strength and muscular definition.', '58781201', '58781201-Band-Bent-over-One-Arm-Kickback-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.689343+00', '1. Secure the resistance band appropriately for Band Bent Over One Arm Kickback. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Complete all reps on one side, then switch to the other side. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Bent Over Single Arm Kickback', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('8d67c3e8-014d-419d-9034-ba1b25826d82', 'Landmine Seated 180s (Landmine)', 'Core', 'Landmine Attachment, Barbell', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Being seated provides stability, allowing you to focus on the working muscles. Core strength is foundational for athletic performance and injury prevention.', '104361201', '104361201-Landmine-Sitting-180s-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.392006+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Landmine Seated 180s. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Landmine Seated 180s', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('8d69bc6b-c485-40ba-9d16-85840bec11cb', 'Squat Twist', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Your abs work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Leg training boosts metabolism and builds functional, real-world strength.', '77071201', '77071201-Squat-Twist-(female)_Thighs_.mp4', 'female', FALSE, '2025-12-03 23:26:38.285955+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. Perfect for targeting your quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 85, 5, 7, FALSE, TRUE, 'squat', 'Squat Twist', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8d799f41-4899-488d-9e3c-01099b553409', 'Hanging Deadbug (Pull-Up Bar)', 'Core', 'Pull-Up Bar', '{"Lower Abs"}'::text[], '{"Hip Flexors","Forearms"}'::text[], 'The Hanging Deadbug is a lower body movement exercise that targets your abs. The hip flexors, grip assist throughout the movement, making this a well-rounded exercise. Hanging adds a grip and core stability component to the exercise. No equipment needed—your body provides all the resistance. Leg training boosts metabolism and builds functional, real-world strength.', '43731201', '43731201-Hanging-Deadbug_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Grip the bar and hang with arms fully extended, engaging your shoulders. 2. Set up in the starting position for Hanging Deadbug. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Hanging Deadbug', 'plank, bird_dog, hollow_hold', TRUE, 'pull_up_bar', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8d7b96a0-ed2b-44c6-934e-7a791fd836db', 'Chest Pull Back', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps"}'::text[], 'The Chest Pull Back is a pulling exercise that develops back strength and muscle. Secondary activation of your triceps provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Back development is crucial for pulling strength and overall upper body function.', '55041201', '55041201-Chest-Pull-Back-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:23.586683+00', '1. Set up in the starting position for Chest Pull Back. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'chest_exercise', 'Chest Pull Back', 'bench_press, chest_fly, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8d7c0d7b-588b-446d-8d2c-d8b7172e36f1', 'Standing Double Hand Row', 'Back', 'Bodyweight', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'This rowing exercise works your delts for improved shoulder strength and aesthetics. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Strong shoulders improve overhead strength and support nearly all upper body movements.', '96181201', '96181201-Standing-Double-Hand-Row-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 72, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Double Hand Row', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8d930555-59da-4761-b8ac-6830e6831f7a', 'Twist Stepback', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic twisting movement gets your heart rate up while developing explosive strength. Your abs work as secondary movers, adding to the training stimulus. Plyometric training builds explosive power that transfers to sports and daily activities.', '57151201', '57151201-Twist-Stepback-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Set up a box or step platform at the appropriate height. 2. Rotate your torso through the movement pattern for Twist Stepback. 3. Control the rotation in both directions—avoid using momentum. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'russian_twist', 'Twist Stepback', 'lat_pulldown, bent_over_row, pull_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8d933a16-34a7-435c-a747-c6c0237fc43e', 'Kneeling Side Plank Raise', 'Core', 'Bodyweight', '{"Core","Abs"}'::text[], '{"Shoulders"}'::text[], 'Strengthen your midsection with this raising movement that works your abs. Secondary activation of your shoulders, lower back provides additional muscle engagement. The kneeling position adds a core stability challenge. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '93451201', '93451201-Kneeling-Side-Plank-Raise-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Kneel on the floor (use a pad for comfort if needed). 2. Raise your arms out to the sides until parallel to the floor. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'side_plank', 'Kneeling Side Plank Raise', 'shoulder_press, front_raise, rear_delt_fly, upright_row', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('8d96048c-e5e8-49aa-810f-60e85185b3e9', 'Multy Chest Press (Machine)', 'Chest', 'Chest Press Machine', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This pressing exercise focuses on your pectorals for improved chest strength and development. Your triceps, front delts work as secondary movers, adding to the training stimulus. The fixed path allows you to focus purely on muscular effort. A well-developed chest contributes to upper body strength and aesthetics. Control the negative portion for maximum muscle engagement.', '105021201', '105021201-Lever-Multy-Chest-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Multy Chest Press. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 78, 7, 8, TRUE, TRUE, 'bench_press', 'Lever Multy Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('8d96a55b-d5d9-4e5a-b6d5-34e6db4eaf52', 'Standing Single Leg Kick And Rotate', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this kicking exercise that develops speed, power, and coordination. Your hip flexors work as secondary movers, adding to the training stimulus. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Great for improving athletic performance, burning calories, and building conditioning.', '93471201', '93471201-Standing-Single-Leg-Kick-and-Rotate-(female)_Plyom.mp4', 'female', FALSE, '2025-12-03 23:26:38.992671+00', '1. Begin in a standing position with good posture. 2. Complete all reps on one side, then switch to the other side. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 47, 7, 8, TRUE, TRUE, 'leg_exercise', 'Standing Single Leg Kick And Rotate', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8d9a65b4-c8d3-4db2-bb9e-f063957a9b59', 'High Knee To Butt Kick', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{"Quads","Calves"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Your hip flexors work as secondary movers, adding to the training stimulus. Regular cardio training builds the aerobic base for better overall fitness.', '71631201', '71631201-High-Knee-to-Butt-Kick-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Set up in the starting position for High Knee To Butt Kick. 2. Execute the movement with proper form, focusing on your cardio. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'glute_kickback', 'High Knee To Butt Kick', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('8daa309e-9e27-48d1-b336-0ac48bf80dc7', 'Standing Balance Stepback And Glute Kickback', 'Legs', 'Bodyweight', '{"Glutes","Hamstrings"}'::text[], '{}'::text[], 'Develop your posterior chain with this kicking movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. The standing position engages your core for stability. Leg training boosts metabolism and builds functional, real-world strength.', '81161201', '81161201-Standing-Balance-Stepback-and-Glute-Kickback-(fema.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Set up a box or step platform at the appropriate height. 2. Stand tall with your feet firmly planted. 3. Keep your upper arm stationary and extend your forearm back. 4. Squeeze at full extension, then return with control. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 52, 5, 7, FALSE, TRUE, 'glute_kickback', 'Standing Balance Stepback And Glute Kickback', 'hip_thrust, glute_bridge, leg_curl', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8db25a92-e3c2-4759-8e85-ea0a6c2114cd', 'Chest Press - Close Grip (TRX)', 'Chest', 'TRX', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Suspension Close Grip Chest Press is an arm pressing exercise targeting your chest. You''ll also feel your triceps, front delts working to support the movement. The TRX allows you to adjust difficulty by changing your body angle. Dedicated arm training builds both strength and muscular definition.', '58751201', '58751201-Suspension-Close-grip-Chest-Press-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:23.172397+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspension Close Grip Chest Press. 2. Use a close/narrow grip (hands closer than shoulder-width). 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'bench_press', 'Suspension Chest Press - Close Grip', 'Suspension Chest Press - Close Grip', FALSE, 'trx', FALSE, 3, 90, 4, 68, 85, 85, 70),
('8dc66cb2-4039-4106-aaae-4eabaaa16241', 'Standing Chest Press (Resistance Band)', 'Chest', 'Resistance Band', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Build a stronger chest with this pressing movement that develops pressing power. You''ll also feel your triceps, front delts working to support the movement. Performing this standing challenges your balance and core engagement. Bands are joint-friendly and portable, perfect for any training environment. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '86061201', '86061201-Resistance-Band-Standing-Chest-Press-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Secure the resistance band appropriately for Resistance Band Standing Chest Press. 2. Stand with feet about shoulder-width apart. 3. Lower the weight toward your chest with control. 4. Press the weight up until your arms are extended (don''t lock elbows). 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'bench_press', 'Standing Chest Press', 'incline_press, decline_press, chest_fly, push_up, dip', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('8dcda264-eba1-47dd-b1d6-547f81b4f47f', 'Crunch On A Bench', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this crunching movement that works your abs. Your hip flexors work as secondary movers, adding to the training stimulus. A strong core improves posture, protects your spine, and enhances all other lifts.', '78221201', '78221201-Crunch-on-a-Bench-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:22.536005+00', '1. Curl your shoulders off the floor by contracting your abs. 2. Don''t pull on your neck—focus on the abdominal contraction. 3. Lower with control, maintaining some tension. 4. Complete all reps with control before resting. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Crunch On A Bench', 'leg_raise, plank, russian_twist, v_up', TRUE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8ddab0a5-9355-4c69-a97b-72d757cf6550', 'Standing Ladder Climb', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'A challenging plyometric exercise, the Standing Ladder Climb builds reactive power and improves conditioning. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '82761201', '82761201-Standing-Ladder-Climb-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:38.7451+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Ladder Climb. 3. Execute the movement with proper form, focusing on your full body. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Standing Ladder Climb', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8df29a29-732d-4484-a168-ae46d65a461d', 'Squat Lunge Jump Complex (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Dumbbell Squat Lunges Jump Complex is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. Dumbbells allow each arm to work independently, helping correct imbalances. Strong legs are the foundation for athletic performance and functional fitness.', '45641201', '45641201-Dumbbell-Squat-Lunges-Jump-Complex_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Squat Lunges Jump Complex. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Explode upward from the bottom, jumping as high as possible. 5. Land softly with bent knees and immediately descend into the next rep. 6. Repeat for the prescribed number of repetitions.', 'Squat', NULL, NULL, NULL, NULL, 4, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 97, 9, 8, TRUE, TRUE, 'squat', 'Squat Lunge Jump Complex', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', TRUE, 'dumbbell', FALSE, 3, 60, 4, 92, 90, 92, 90),
('8e0fd04a-36d0-4754-8e32-c716e68829d6', 'Split Squat Front Foot Elevated (Dumbbell)', 'Legs', 'Dumbbells', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This squatting movement emphasizes your quadriceps for stronger, more powerful legs. Secondary activation of your glutes, hamstrings provides additional muscle engagement. The dumbbell variation provides freedom of movement and greater range of motion. Lower body strength improves everything from walking to heavy compound lifts.', '77841201', '77841201-Dumbbell-Split-Squat-Front-Foot-Elevanted_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Split Squat Front Foot Elevanted. 2. Push your hips back and bend your knees to lower your body. 3. Keep your chest up and knees tracking over your toes. 4. Drive through your heels to stand back up, squeezing your glutes at the top. 5. Continue for your target rep count, maintaining good form throughout.', 'Squat', NULL, NULL, NULL, NULL, 2, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 9, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'split_squat', 'Split Squat Front Foot Elevanted', 'lunge, bulgarian_split_squat, squat', TRUE, 'dumbbell', FALSE, 4, 120, 5, 92, 90, 92, 90),
('8e12876d-29ff-458b-83b3-919366e69d30', 'Hopping High Knee Tap', 'Legs', 'Bodyweight', '{"Hip Flexors"}'::text[], '{"Quads","Calves"}'::text[], 'This dynamic movement movement gets your heart rate up while developing explosive strength. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '96791201', '96791201-Hopping-High-Knee-Tap-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Set up in the starting position for Hopping High Knee Tap. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'high_knees', 'Hopping High Knee Tap', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('8e3e4faa-0f2a-4f54-844c-93087aa3449d', 'Chest Press (Stability Ball, Barbell)', 'Chest', 'Barbell, Stability Ball', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Barbell Chest Press On Stability Ball is a pressing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. Using a barbell provides stability for progressive overload. A well-developed chest contributes to upper body strength and aesthetics.', '37291201', '37291201-Barbell-Chest-Press-on-Stability-Ball_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Grip a barbell with hands at the appropriate width for Barbell Chest Press On Stability Ball. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 74, 7, 8, TRUE, TRUE, 'bench_press', 'Chest Press On Stability Ball', 'incline_press, decline_press, chest_fly, push_up, dip', TRUE, 'barbell', FALSE, 3, 90, 4, 95, 80, 65, 95),
('8e430de4-bb9c-4d7d-9338-f3ea9ad93f88', 'Split Stance Bent Over Row (Dumbbell)', 'Back', 'Dumbbells', '{"Back","Lats"}'::text[], '{"Biceps","Rear Delts"}'::text[], 'The Dumbbell Split Stance Bent Over Row is a rowing exercise that builds thickness in your upper back. You''ll also feel your biceps, lats working to support the movement. Bending over allows gravity to provide resistance in a different plane. Dumbbells allow each arm to work independently, helping correct imbalances. A strong back improves posture, prevents injury, and balances pressing movements.', '74741201', '74741201-Dumbbell-Split-Stance-Bent-Over-Row-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.732034+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Split Stance Bent Over Row. 2. Hinge at your hips, pushing them back while keeping your back flat. 3. Pull the weight toward your torso, leading with your elbow(s). 4. Squeeze your shoulder blades together at the peak contraction. 5. Extend back out with control, feeling the stretch in your back. 6. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 82, 7, 9, TRUE, FALSE, 'bent_over_row', 'Split Stance Bent Over Row', 'cable_row, dumbbell_row, t_bar_row, lat_pulldown', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('8e46b29e-202d-4eb3-9894-005f78b8e150', 'Z Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Dumbbell Z Press is a pressing exercise that targets your delts for shoulder development. Dumbbells allow each arm to work independently, helping correct imbalances. Shoulder development enhances both performance and upper body aesthetics.', '68901201', '68901201-Dumbbell-Z-Press_Shoulders_.mp4', 'male', FALSE, '2025-12-03 23:26:24.577164+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Z Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 82, 7, 8, TRUE, TRUE, 'shoulder_press', 'Z Press', 'lateral_raise, front_raise, rear_delt', TRUE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('8e6c3d2b-1168-45a2-8d28-7e779f157d5e', 'Burpee With Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'This cardio exercise keeps your heart rate elevated for improved cardiovascular fitness. Secondary activation of your triceps, front delts provides additional muscle engagement. Regular cardio training builds the aerobic base for better overall fitness.', '34561201', '34561201-Burpee-with-Push-up-(female)_Cardio_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Exhale during the exertion phase of the movement. Perfect for targeting your cardio.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'push_up', 'Burpee With Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('8e795b5c-6427-4cb1-86fc-dbdb1357d9fc', 'Seated Forward Reach Arms Interlock', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Seated Forward Reach Arms Interlock provides a deep stretch for your core, ideal for recovery and mobility work. The seated position helps isolate the target muscles by removing momentum. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82401201', '82401201-Seated-Forward-Reach-Arms-Interlock-(female)_Stret.mp4', 'female', FALSE, '2025-12-03 23:26:36.717157+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Move into the stretch position for Seated Forward Reach Arms Interlock. 3. Ease into the stretch until you feel gentle tension (not pain). 4. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 37, 7, 8, TRUE, TRUE, 'hamstring_stretch', 'Seated Forward Reach Arms Interlock', 'bicep_curl, tricep_extension, hammer_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8e7eafd9-97c6-40ee-8996-d722562ba6c5', 'Standing Side Bend (Bent Arm)', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'Build a stronger core with the Standing Side Bend (bent Arm), focusing on your abs. The abs assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. This bodyweight exercise requires no equipment and can be done anywhere. A strong core improves posture, protects your spine, and enhances all other lifts.', '43221201', '43221201-Standing-Side-Bend-(bent-arm)-(male)_Waist.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Stand tall with your feet firmly planted. 2. Set up in the starting position for Standing Side Bend. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Stretch', 52, 7, 8, TRUE, TRUE, 'side_bend', 'Standing Side Bend', 'russian_twist, woodchop, oblique_crunch', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8e825540-9411-43a2-963b-08b0a607e013', 'Seated Shoulder Stretch (Chair)', 'Shoulders', 'Chair', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Use this stretch to open up your shoulders area and enhance overall flexibility. Your upper back work as secondary movers, adding to the training stimulus. Being seated provides stability, allowing you to focus on the working muscles. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '91641201', '91641201-Sitting-Shoulder-Stretch-on-a-Chair-(female)_Stret.mp4', 'female', FALSE, '2025-12-03 23:26:37.877283+00', '1. Position yourself with a sturdy chair for support or as part of the movement. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Move into the stretch position for Seated Shoulder Stretch On A Chair. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'shoulder_stretch', 'Seated Shoulder Stretch On A Chair', 'stretch_chest, stretch_tricep, stretch_lat', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('8e96b5ba-37af-4e4f-8942-3dfd56da6e87', 'Incline Pronated Grip Front Raise (EZ Bar)', 'Shoulders', 'EZ Bar', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'This raising exercise works your front delts for improved shoulder strength and aesthetics. The incline angle shifts emphasis toward the upper portion of the target muscles. Shoulder development enhances both performance and upper body aesthetics.', '96501201', '96501201-EZ-bar-Incline-Pronated-Grip-Front-Raise_Shoulders.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Grip the EZ bar on the angled portions for a comfortable wrist position. 2. Use an overhand (pronated) grip with palms facing down/away. 3. Raise the weight in front of you to shoulder height. 4. Lower with control, maintaining tension throughout. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 73, 5, 7, FALSE, TRUE, 'front_raise', 'EZ Bar Incline Pronated Grip Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'ez_bar', FALSE, 3, 60, 2, 95, 80, 65, 95),
('8e97e6a5-4e4f-4ed7-9ebc-813723140674', 'Lying Single Bent Leg Opposite Reach', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Single Bent Leg Opposite Reach is a lower body movement exercise that targets your core. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Lower body strength improves everything from walking to heavy compound lifts.', '96281201', '96281201-Lying-Single-Bent-Leg-Opposite-Reach-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:35.38119+00', '1. Lie down in the appropriate position for Lying Single Bent Leg Opposite Reach. 2. Set up in the starting position for Lying Single Bent Leg Opposite Reach. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Lying Single Bent Leg Opposite Reach', 'squat, lunge, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8e9fff91-18e2-485e-97f1-4cb073745cee', 'Squat Side Shuffle', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'This dynamic squatting movement gets your heart rate up while developing explosive strength. You''ll also feel your glutes, hamstrings working to support the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. Perfect for including in both strength and hypertrophy programs.', '90151201', '90151201-Bodyweight-Squat-Side-Shuffle-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Control the movement—avoid using momentum.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 85, 9, 8, TRUE, TRUE, 'shuffle', 'Squat Side Shuffle', 'leg_press, leg_extension, leg_curl, lunge, front_squat, hack_squat', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('8eaef8e2-5d89-4435-a095-6dc0454223a8', 'Elbows Back Stretch', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'Build a stronger chest with this stretching movement that develops pressing power. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '46721201', '46721201-Elbows-Back-Stretch-(male)_Chest.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Set up in the starting position for Elbows Back Stretch. 2. Execute the movement with proper form, focusing on your chest. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 40, 2, 6, FALSE, TRUE, 'back_stretch', 'Elbows Back Stretch', 'stretch_hip, stretch_hamstring, stretch_shoulder', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('8ebf6cbd-a0fa-41ae-9af0-049cb741a501', 'Wide Pulldown - Neutral Grip (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'This pulling exercise emphasizes your lats for improved back development. The biceps, upper back assist throughout the movement, making this a well-rounded exercise. Cables provide constant tension throughout the full range of motion. A strong back improves posture, prevents injury, and balances pressing movements.', '55801201', '55801201-Cable-Neutral-Grip-Wide-Pulldown-(VERSION-2)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:22.123147+00', '1. Adjust the cable machine to the correct height and attachment for Cable Neutral Grip Wide Pulldown. 2. Use a wide grip (wider than shoulder-width) for this variation. 3. Pull the bar/handle down toward your upper chest. 4. Drive your elbows down and back, squeezing your lats. 5. Control the weight back up without letting it yank your arms. 6. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Wide Pulldown - Neutral Grip', 'Wide Pulldown - Neutral Grip', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('8ecdbb9f-e13f-4c4d-9d06-e52f2c823ee9', 'Round The World Curtsey', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Build power and athleticism with this high-intensity movement exercise that challenges your entire body. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities. Aim for full range of motion on every rep.', '73541201', '73541201-Round-The-World-Curtsey-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Set up in the starting position for Round The World Curtsey. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'general_exercise', 'Round The World Curtsey', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8eea268b-7515-4320-a356-70b2f15b8fe2', 'Seated Pronation Supination Foot', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build stronger calves with this targeted movement exercise. The seated position helps isolate the target muscles by removing momentum. Strong legs are the foundation for athletic performance and functional fitness.', '105641201', '105641201-Seated-Pronation-Supination-Foot-(male)_Calves_.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Set up in the starting position for Seated Pronation Supination Foot. 3. Execute the movement with proper form, focusing on your calves. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Pronation Supination Foot', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8f0b469a-d528-4805-a782-65cc8831abc6', 'Frog Hip Thrust', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'The Frog Hip Thrust is a hip-dominant thrusting exercise that targets your glutes. Secondary activation of your hamstrings provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '27571201', '27571201-Frog-Hip-Thrust-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:33.640031+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_thrust', 'Frog Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8f116ca9-368e-4513-ad54-e10dfe61b0ac', 'Walking Toe Touch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. You''ll also feel your hip flexors working to support the movement. No equipment needed—your body provides all the resistance. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '75401201', '75401201-Walking-Toe-Touch-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Set up in the starting position for Walking Toe Touch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'toe_touch', 'Walking Toe Touch', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('8f122fc3-3a41-4c9c-97f2-02a4a1c119b9', 'Half Boat Pose Ardha Navasana', 'Full Body', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Half Boat Pose Ardha Navasana provides a deep stretch for your full body, ideal for recovery and mobility work. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '63001201', '63001201-Half-Boat-Pose-Ardha-Navasana-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:33.778367+00', '1. Move into the stretch position for Half Boat Pose Ardha Navasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Half Boat Pose Ardha Navasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65);
INSERT INTO _exercise_staging (id, name, category, equipment, primary_muscles, secondary_muscles, description, video_code, video_filename, gender, is_custom, created_at, steps_to_perform, movement_pattern, force_type, movement_type, laterality, plane_of_motion, difficulty_level, complexity_score, strength_rating, hypertrophy_rating, power_rating, endurance_rating, body_position, bench_angle, grip_type, grip_width, optimal_rep_range_min, optimal_rep_range_max, placement_in_workout, fatigability, popularity_score, home_gym_friendly, instructions, workout_type, practicality_score, fat_loss_rating, general_fitness_rating, is_compound, supersetable, exercise_family, base_exercise_name, complementary_families, is_equipment_primary, equipment_category, duration_based, recommended_sets, rest_seconds, muscles_worked_count, priority_build_muscle, priority_get_lean, priority_home, priority_gym) VALUES
('8f207f34-ecd4-4f6d-817b-048c3d81b3f1', 'Hollow Body Tuck', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. Secondary activation of your hip flexors provides additional muscle engagement. No equipment needed—your body provides all the resistance. Building core stability helps with everything from heavy deadlifts to daily activities.', '76851201', '76851201-Hollow-Body-Tuck-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:26.271124+00', '1. Set up in the starting position for Hollow Body Tuck. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'hollow_hold', 'Hollow Body Tuck', 'squat, bench_press, deadlift', FALSE, 'bodyweight', TRUE, 3, 90, 4, 70, 88, 95, 65),
('8f227a49-2065-46db-984b-643bc1d7fe45', 'Bicycle Twisting Crunch', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{}'::text[], 'This crunching movement focuses on your obliques for a complete core workout. The abs assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '1471201', '01471201-Bycicle-Twisting-Crunch_Waist-FIX_.mp4', 'female', FALSE, '2025-12-03 23:26:31.723232+00', '1. Bring one knee toward chest while extending the other leg. 2. Rotate to bring opposite elbow toward the bent knee. 3. Alternate sides in a pedaling motion. 4. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 62, 5, 7, FALSE, TRUE, 'cycling', 'Bicycle Twisting Crunch', 'crunch, russian_twist, leg_raise', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8f2fe43b-62e6-4000-95cb-bcde9b221bae', 'Fist Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Target your chest with the Fist Push Up, an effective pushing movement for upper body strength. You''ll also feel your triceps, front delts working to support the movement. No equipment needed—your body provides all the resistance. A well-developed chest contributes to upper body strength and aesthetics.', '82701201', '82701201-Fist-Push-up-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Fist Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8f34a752-c6dd-4155-87af-9761b02a0559', 'Side To Side Squat', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side To Side Squat is a squatting exercise that primarily loads your quadriceps. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '80811201', '80811201-Side-to-Side-Squat-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:29.971345+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Focus on maintaining proper breathing throughout. An effective movement for your legs routine.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Side To Side Squat', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8f37854e-ae92-441b-a40d-1f6038802af0', 'Standing Double Crunch Knee Drive', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'A challenging plyometric exercise, the Standing Double Crunch Knee Drive builds reactive power and improves conditioning. The hip flexors assist throughout the movement, making this a well-rounded exercise. The standing position engages your core for stability. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '103081201', '103081201-Standing-Double-Crunch-Knee-Drive-(female)_Plyome.mp4', 'female', FALSE, '2025-12-03 23:26:38.570929+00', '1. Stand tall with your feet firmly planted. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Repeat for the prescribed number of repetitions. Focus on the mind-muscle connection.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 72, 5, 7, FALSE, TRUE, 'knee_drive', 'Standing Double Crunch Knee Drive', 'butt_kicks, jumping_jack, mountain_climber', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8f3ae505-ba91-4560-850b-c1eecebd2ead', 'Kneeling Leg Curl (Machine)', 'Legs', 'Leg Curl Machine', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'Strengthen the back of your thighs with this curling exercise. Your calves work as secondary movers, adding to the training stimulus. Kneeling helps eliminate lower body momentum from the movement. The machine guides your movement path for safer, more controlled repetitions. Leg training boosts metabolism and builds functional, real-world strength.', '5821201', '05821201-Lever-Kneeling-Leg-Curl-(plate-loaded)_Thighs.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Kneeling Leg Curl. 2. Kneel on the floor (use a pad for comfort if needed). 3. Curl your heels toward your glutes by bending at the knees. 4. Squeeze your hamstrings at peak contraction. 5. Extend legs back out with control. 6. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 88, 7, 8, TRUE, TRUE, 'leg_curl', 'Lever Kneeling Leg Curl', 'romanian_deadlift, hip_thrust', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('8f4e26c8-ce2f-454c-aebf-761941b0f56f', 'Weighted V Up Passes With Pad', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Secondary activation of your hip flexors provides additional muscle engagement. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '55111201', '55111201-Weighted-V-up-Passes-with-Pad_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Set up in the starting position for Weighted V Up Passes With Pad. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Repeat for the prescribed number of repetitions. Ensure full range of motion on each rep.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'v_up', 'Weighted V Up Passes With Pad', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8f57f97d-4df0-4f60-bc52-a8bb1d08a2bb', 'Standing Shoulders Roll', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'The Standing Shoulders Roll is a movement exercise that targets your delts for shoulder development. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Shoulder development enhances both performance and upper body aesthetics.', '107011201', '107011201-Standing-Shoulders-Roll-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:38.870314+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Shoulders Roll. 3. Execute the movement with proper form, focusing on your delts. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'shoulder_exercise', 'Standing Shoulders Roll', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8f666be5-9ffa-4b98-9baf-498af65470f8', 'Leg Raise (Bent Knee)', 'Core', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Target your abs with this raising stretch that helps restore range of motion. Your hip flexors work as secondary movers, adding to the training stimulus. Include this in your routine for better mobility and reduced muscle tension.', '28501201', '28501201-Leg-Raise-(bent-knee)-(female)_Pilates_.mp4', 'female', FALSE, '2025-12-03 23:26:34.603963+00', '1. Keeping legs mostly straight, raise them toward the ceiling. 2. Lower with control, stopping just before touching down. 3. Move into the stretch position for Leg Raise. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8f6b6bc3-75b5-46a3-9412-a7654cc582c7', 'Atomic Sit Up', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Atomic Sit Up is a core movement exercise that primarily targets your abs. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. Core strength is foundational for athletic performance and injury prevention.', '86251201', '86251201-Atomic-Sit-Up-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:27.384461+00', '1. Set up in the starting position for Atomic Sit Up. 2. Execute the movement with proper form, focusing on your abs. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Atomic Sit Up', 'leg_raise, plank, russian_twist, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8f7034a7-161a-4e01-8a35-0e8cdba7e25d', 'Front Raise And Pullover (Barbell)', 'Shoulders', 'Barbell, Flat Bench', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'This pulling exercise focuses on your pectorals for improved chest strength and development. The lats, triceps assist throughout the movement, making this a well-rounded exercise. Barbells enable bilateral loading for building raw strength. A well-developed chest contributes to upper body strength and aesthetics.', '401201', '00401201-Barbell-Front-Raise-And-Pullover_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.937212+00', '1. Grip a barbell with hands at the appropriate width for Barbell Front Raise And Pullover. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise And Pullover', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('8f990154-8691-4ca3-b6b4-60a54de7bf55', 'Criss Cross Jump', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'A challenging plyometric exercise, the Criss Cross Jump builds reactive power and improves conditioning. You''ll also feel your shoulders, core working to support the movement. No equipment needed—your body provides all the resistance. Plyometric training builds explosive power that transfers to sports and daily activities.', '47071201', '47071201-Criss-Cross-Jump_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:29.242428+00', '1. Set up in the starting position for Criss Cross Jump. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'boxing', 'Criss Cross Jump', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('8fa17482-83ee-4256-9c9d-cf11af4bd37d', 'Shoulder Tap Jack Plank', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'This dynamic stabilization movement gets your heart rate up while developing explosive strength. Your shoulders, lower back work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements.', '71501201', '71501201-Shoulder-Tap-Jack-Plank-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:26.507873+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Continue for your target rep count, maintaining good form throughout. Control the movement—avoid using momentum. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'plank', 'Shoulder Tap Jack Plank', 'side_plank, dead_bug, hollow_hold', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('8fa709ab-ede8-4060-8b0a-40ccb6c37fd0', 'Jumping Split Jack', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Calves"}'::text[], 'Elevate your training with this jumping exercise that develops speed, power, and coordination. You''ll also feel your quads, calves working to support the movement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '55841201', '55841201-Jumping-Split-Jack-(Male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:27.805708+00', '1. Set up in the starting position for Jumping Split Jack. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 50, 9, 8, TRUE, TRUE, 'general_exercise', 'Jumping Split Jack', 'burpee, high_knees, jump_rope', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('8faadcf7-bf4a-4c1d-85e5-0ab86348e75f', '90 To 90 Hip Leans', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'Use this stretch to open up your hips area and enhance overall flexibility. Include this in your routine for better mobility and reduced muscle tension. Maintain proper breathing - exhale during the effort phase.', '82651201', '82651201-90-to-90-Hip-Leans-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:30.292204+00', '1. Move into the stretch position for 90 To 90 Hip Leans. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'glute_exercise', '90 To 90 Hip Leans', 'hip_thrust, lunge, squat', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8fb5d340-e77d-4e71-b0f9-ff397f5f5e87', 'Rowing - Straight Back (Rowing Machine)', 'Back', 'Row Machine', '{"Upper Back"}'::text[], '{"Lats","Biceps","Rear Delts"}'::text[], 'Enhance your stamina and burn calories with this effective cardio movement. The biceps, rear delts assist throughout the movement, making this a well-rounded exercise. The fixed path allows you to focus purely on muscular effort. Cardiovascular exercise improves heart health, endurance, and helps manage weight.', '22701201', '22701201-Rowing-Straight-Back-(with-rowing-machine)-(female)_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:36.581585+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Rowing Straight Back. 2. Pull the weight toward your torso, leading with your elbow(s). 3. Squeeze your shoulder blades together at the peak contraction. 4. Extend back out with control, feeling the stretch in your back. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, FALSE, NULL, 'Strength', 78, 7, 9, TRUE, FALSE, 'rowing_machine', 'Rowing Straight Back', 'cycling, running, deadlift', FALSE, 'machine', FALSE, 4, 120, 4, 80, 75, 20, 88),
('8fb9b525-f3b4-4b7f-bd7a-b886abe98c0a', 'Seated Single Leg Hamstring Stretch (Gymnastic Rings)', 'Legs', 'Gymnastic Rings', '{"Hamstrings"}'::text[], '{"Glutes"}'::text[], 'The Seated Single Leg Hamstring Stretch targets your hamstrings through a controlled stretching motion. The seated position helps isolate the target muscles by removing momentum. Leg training boosts metabolism and builds functional, real-world strength.', '73811201', '73811201-Seated-Single-Leg-Hamstring-Stretch-(male)_Thighs_.mp4', 'male', FALSE, '2025-12-03 23:26:26.39056+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Complete all reps on one side, then switch to the other side. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, 'Seated', NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 25, 2, 6, FALSE, TRUE, 'hamstring_stretch', 'Seated Single Leg Hamstring Stretch', 'stretch_hip, stretch_calf, stretch_back', FALSE, 'gymnastic_rings', TRUE, 1, 30, 2, 68, 85, 85, 70),
('8fbc37b6-0b00-4808-a528-9ab3c7ec1bce', 'Double Pulse Elbow Fly', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Build a stronger chest with this flying movement that develops pressing power. Your front delts work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts. This is a great exercise for all fitness levels with proper scaling.', '63071201', '63071201-Double-Pulse-Elbow-Fly-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:32.624497+00', '1. With a slight bend in your elbows, move the weight in a wide arc. 2. Squeeze your chest muscles at the center/top of the movement. 3. Return with control, feeling the stretch at the bottom. 4. At the bottom or top, pulse up and down in small movements before completing the rep. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'pulse', 'Double Pulse Elbow Fly', 'bench_press, incline_bench_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8fbd257c-240f-4dfc-93d4-c40f49149488', 'Lizard Lunge', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Use this stretch to open up your quads area and enhance overall flexibility. Secondary activation of your glutes, hamstrings provides additional muscle engagement. Include this in your routine for better mobility and reduced muscle tension. Quality repetitions are more important than quantity.', '80711201', '80711201-Lizard-Lunge-(beginner)-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Step forward into a lunge until both knees are at about 90 degrees. 2. Push through your front/working leg to return to the starting position. 3. Move into the stretch position for Lizard Lunge. 4. Ease into the stretch until you feel gentle tension (not pain). 5. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_stretch', 'Lizard Lunge', 'squat, split_squat, step_up, leg_press', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8fc4f209-9c2b-4741-b870-e93f10fff94f', 'Seated Neutral Wrist Curl (Dumbbell)', 'Arms', 'Dumbbells, Flat Bench', '{"Forearms"}'::text[], '{}'::text[], 'Build grip strength and forearm size with this curling exercise. The forearms assist throughout the movement, making this a well-rounded exercise. Being seated provides stability, allowing you to focus on the working muscles. Dumbbells allow each arm to work independently, helping correct imbalances. Dedicated arm training builds both strength and muscular definition.', '26321201', '26321201-Dumbbell-Seated-Neutral-Wrist-Curl-(female)_Forearms.mp4', 'female', FALSE, '2025-12-03 23:26:33.168801+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Seated Neutral Wrist Curl. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Keep your elbows in a fixed position throughout the movement. 4. Curl the weight up by contracting your biceps, squeezing at the top. 5. Lower with control, resisting the weight on the way down. 6. Continue for your target rep count, maintaining good form throughout. Keep the movement smooth and controlled.', 'Curl', 'Pull', NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Seated', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 84, 5, 7, FALSE, TRUE, 'wrist_curl', 'Seated Neutral Wrist Curl', 'tricep_pushdown, tricep_extension, hammer_curl, preacher_curl', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('8fc76607-5730-4077-8da3-a125b3dfe213', 'Side Step Overhead Swing Side Leg Raise', 'Legs', 'Bodyweight', '{"Lower Abs"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Side Step Overhead Swing Side Leg Raise is a lower body raising exercise that targets your hip abductors. Secondary activation of your glutes provides additional muscle engagement. Lower body strength improves everything from walking to heavy compound lifts.', '83981201', '83981201-Side-Step-Overhead-Swing-Side-Leg-Raise-(male)_Ply.mp4', 'male', FALSE, '2025-12-03 23:26:23.056255+00', '1. Set up a box or step platform at the appropriate height. 2. Hinge at your hips, letting the weight swing back between your legs. 3. Explosively drive hips forward, propelling the weight forward/up. 4. Let gravity bring it back as you hinge for the next rep. 5. Complete all reps with control before resting. Engage your stabilizer muscles for better control.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Side Step Overhead Swing Side Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('8fcae1cf-6a10-4741-bbb7-d48c0ba7aac9', 'Squat Bounce', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Build power and athleticism with this high-intensity squatting exercise that challenges your entire body. You''ll also feel your glutes, hamstrings working to support the movement. This bodyweight exercise requires no equipment and can be done anywhere. Develops fast-twitch muscle fibers for quicker, more powerful movements. A staple exercise that belongs in most training programs.', '82491201', '82491201-Squat-Bounce-(male)_Plyometrics_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Squat Bounce', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8fce4fa1-bd49-4ace-8bf6-91d232726f40', 'Front Raise (Band)', 'Shoulders', 'Resistance Band', '{"Front Delts"}'::text[], '{"Chest"}'::text[], 'The Band Front Raise is a raising exercise that targets your front delts for shoulder development. Resistance bands provide accommodating resistance that increases through the range of motion. Shoulder development enhances both performance and upper body aesthetics.', '107251201', '107251201-Band-Front-Raise-(female)_Shoulders_.mp4', 'female', FALSE, '2025-12-03 23:26:30.685158+00', '1. Secure the resistance band appropriately for Band Front Raise. 2. Raise the weight in front of you to shoulder height. 3. Lower with control, maintaining tension throughout. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 75, 5, 7, FALSE, TRUE, 'front_raise', 'Front Raise', 'shoulder_press, lateral_raise, rear_delt_fly', FALSE, 'band', FALSE, 3, 60, 2, 60, 85, 90, 50),
('8fe00d2f-4675-47ad-8021-2ad5267ff8e3', 'Pullover Catch (Medicine Ball)', 'Chest', 'Medicine Ball', '{"Chest"}'::text[], '{"Lats","Triceps"}'::text[], 'Build a stronger back with this pulling movement targeting your chest. Your lats, triceps work as secondary movers, adding to the training stimulus. A strong back improves posture, prevents injury, and balances pressing movements.', '105951201', '105951201-Medicine-Ball-Pullover-Catch-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:20.667107+00', '1. Hold a medicine ball at the appropriate position for Medicine Ball Pullover Catch. 2. With arms slightly bent, lower the weight behind your head in an arc. 3. Pull the weight back over your chest, squeezing your lats and chest. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'pullover', 'Medicine Ball Pullover Catch', 'bicep_curl, face_pull, lat_pulldown', FALSE, 'medicine_ball', FALSE, 3, 90, 4, 70, 88, 95, 65),
('8fe6da8d-4b04-4d5a-a778-b817f143aa6a', 'Superman Lift And Lat Pulldown (Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Glutes","Upper Back"}'::text[], 'The Superman Lift And Lat Pulldown is a lower body pulling exercise that targets your lats. Your biceps, upper back work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Strong legs are the foundation for athletic performance and functional fitness.', '95541201', '95541201-Superman-Lift-And-Lat-Pulldown-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:39.340041+00', '1. Pull the bar/handle down toward your upper chest. 2. Drive your elbows down and back, squeezing your lats. 3. Control the weight back up without letting it yank your arms. 4. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 80, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Superman Lift And Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('8fece065-71c3-4734-9571-7882e7444b81', 'Stepper (Machine)', 'Legs', 'Lever Machine', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'The Lever Stepper is a cardiovascular exercise that improves endurance and heart health. Secondary activation of your quads provides additional muscle engagement. The fixed path allows you to focus purely on muscular effort. Regular cardio training builds the aerobic base for better overall fitness.', '9381201', '09381201-Lever-stepper_Cardio.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Stepper. 2. Set up a box or step platform at the appropriate height. 3. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 58, 7, 8, TRUE, TRUE, 'general_exercise', 'Lever Stepper', 'squat, bench_press, deadlift', FALSE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('8fef14d6-5617-4c4c-ac44-0fab9fc39866', 'Split Stance Sigle Arm Overhead Press (Dumbbell)', 'Shoulders', 'Dumbbells', '{"Front Delts"}'::text[], '{"Side Delts","Triceps"}'::text[], 'The Dumbbell Split Stance Sigle Arm Overhead Press is a pressing exercise that targets your delts for shoulder development. You''ll also feel your triceps working to support the movement. Dumbbells allow each arm to work independently, helping correct imbalances. Strong shoulders improve overhead strength and support nearly all upper body movements.', '74791201', '74791201-Dumbbell-Split-Stance-Sigle-Arm-Overhead-Press-(ma.mp4', 'male', FALSE, '2025-12-03 23:26:26.93819+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Split Stance Sigle Arm Overhead Press. 2. Start with the weight at shoulder level. 3. Press directly overhead until your arms are fully extended. 4. Lower back to shoulder level with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 10, 10, NULL, 4, NULL, NULL, NULL, NULL, 5, 8, NULL, 8, NULL, TRUE, NULL, 'Strength', 97, 7, 9, TRUE, FALSE, 'shoulder_press', 'Split Stance Sigle Arm Overhead Press', 'lateral_raise, front_raise, rear_delt', FALSE, 'dumbbell', FALSE, 4, 120, 4, 92, 90, 92, 90),
('8ff4a3e9-7c75-4581-a86f-d35e09d47622', 'Child Pose', 'Back', 'Bodyweight', '{"Lats"}'::text[], '{"Lower Back"}'::text[], 'The Child Pose provides a deep stretch for your back, ideal for recovery and mobility work. You''ll also feel your hips working to support the movement. Include this in your routine for better mobility and reduced muscle tension.', '9451201', '09451201-Child-Pose-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:32.374165+00', '1. Move into the stretch position for Child Pose. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'back_stretch', 'Child Pose', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('900c0aef-d47d-4243-8c2d-ad85b3b2a3f8', 'Slight Squat Back Shoulder Rotation', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this squatting exercise that develops speed, power, and coordination. Your glutes, hamstrings work as secondary movers, adding to the training stimulus. This bodyweight exercise requires no equipment and can be done anywhere. Great for improving athletic performance, burning calories, and building conditioning.', '78141201', '78141201-Slight-Squat-Back-Shoulder-Rotation-(female)_Plyom.mp4', 'female', FALSE, '2025-12-03 23:26:37.99429+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. 4. Complete all reps with control before resting. Exhale during the exertion phase of the movement. Great for building strength in your quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Slight Squat Back Shoulder Rotation', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('90214bd9-ddaa-4347-825d-20cbd5b303f1', 'Lying Extension (Barbell)', 'Arms', 'Barbell, Flat Bench', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. The lying position provides back support and helps isolate the target muscles. Barbells enable bilateral loading for building raw strength. Arm strength supports grip, pulling, and pushing in compound movements.', '571201', '00571201-Barbell-Lying-extension_Upper-arms.mp4', 'male', FALSE, '2025-12-03 23:26:27.504261+00', '1. Grip a barbell with hands at the appropriate width for Barbell Lying Extension. 2. Lie down in the appropriate position for Barbell Lying Extension. 3. Extend through the target joint(s) for Barbell Lying Extension. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'general_exercise', 'Lying Extension', 'squat, bench_press, deadlift', FALSE, 'barbell', FALSE, 3, 60, 2, 95, 80, 65, 95),
('904aed60-cb6e-46c4-881e-76eb03d268e6', 'Triceps Kickback Heel Tap', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Rear Delts"}'::text[], 'This dynamic kicking movement gets your heart rate up while developing explosive strength. The hamstrings assist throughout the movement, making this a well-rounded exercise. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '85211201', '85211201-Triceps-Kickback-Heel-Tap-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Keep your upper arm stationary and extend your forearm back. 2. Squeeze at full extension, then return with control. 3. Continue for your target rep count, maintaining good form throughout. Start with lighter weight to perfect your form.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 50, 5, 7, FALSE, TRUE, 'tricep_kickback', 'Triceps Kickback Heel Tap', 'tricep_pushdown, tricep_extension', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('904d0f9d-072d-41fb-baa0-13984058dff1', 'Low Fly (Kettlebell)', 'Chest', 'Kettlebell', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Kettlebell Low Fly, an effective flying movement for upper body strength. Secondary activation of your front delts provides additional muscle engagement. Kettlebells are excellent for building functional, real-world strength. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '66221201', '66221201-Kettlebell-Low-Fly-(male)_Chest_.mp4', 'male', FALSE, '2025-12-03 23:26:27.263406+00', '1. Select an appropriately weighted kettlebell for Kettlebell Low Fly. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 78, 5, 7, FALSE, TRUE, 'chest_fly', 'Low Fly', 'bench_press, incline_press, push_up', FALSE, 'kettlebell', FALSE, 3, 60, 2, 75, 88, 88, 78),
('905597c0-ae73-47f8-9412-48241804f90c', 'Plank Leg Raise', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build a stronger core with the Plank Leg Raises, focusing on your abs. Secondary activation of your hip flexors provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '55431201', '55431201-Plank-Leg-Raises-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Complete all reps with control before resting. Maintain a neutral spine throughout. A solid choice for core day.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'leg_raise', 'Plank Leg Raise', 'crunch, plank, v_up', FALSE, 'bodyweight', TRUE, 3, 60, 2, 70, 88, 95, 65),
('90733a1c-9695-44d0-9895-378175634ccf', 'Seated Single Arm Wide Lat Pulldown (Machine, Cable)', 'Back', 'Cables', '{"Lats"}'::text[], '{"Biceps","Upper Back"}'::text[], 'Build lat width and pulling strength with this pulling movement. You''ll also feel your biceps, upper back working to support the movement. The seated position helps isolate the target muscles by removing momentum. The machine guides your movement path for safer, more controlled repetitions. A strong back improves posture, prevents injury, and balances pressing movements.', '86921201', '86921201-Lever-Seated-Single-Arm-Wide-Lat-Pulldown-(male)_B.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Single Arm Wide Lat Pulldown. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Use a wide grip (wider than shoulder-width) for this variation. 4. Pull the bar/handle down toward your upper chest. 5. Drive your elbows down and back, squeezing your lats. 6. Control the weight back up without letting it yank your arms. 7. Complete all reps on one side, then switch to the other side. 8. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 8, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'lat_pulldown', 'Lever Seated Single Arm Wide Lat Pulldown', 'pull_up, bent_over_row, cable_row, face_pull', TRUE, 'cable', FALSE, 3, 90, 4, 85, 88, 30, 92),
('907bbe18-6908-45d5-b76c-a68c65cc3dea', 'Quadruped Shoulder Cars', 'Shoulders', 'Bodyweight', '{"Shoulders"}'::text[], '{"Traps"}'::text[], 'Use this stretch to open up your delts area and enhance overall flexibility. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '82541201', '82541201-Quadruped-Shoulder-CARs-(VERSION-2)-(female)_Stret.mp4', 'female', FALSE, '2025-12-03 23:26:35.936279+00', '1. Move into the stretch position for Quadruped Shoulder Cars. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch. Keep tension on the target muscles throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'bird_dog', 'Quadruped Shoulder Cars', 'lateral_raise, shoulder_press, front_raise', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('90835329-5d51-4369-8707-2d6db0ed540b', 'Middle Fly (Cable)', 'Chest', 'Cables', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'This flying exercise focuses on your pectorals for improved chest strength and development. You''ll also feel your front delts working to support the movement. Cables provide constant tension throughout the full range of motion. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '1881201', '01881201-Cable-Middle-Fly_Chest-FIX_.mp4', 'male', FALSE, '2025-12-03 23:26:20.982555+00', '1. Set the cable pulley to mid-height (chest level) and attach the appropriate handle. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 12, 20, NULL, 4, NULL, FALSE, NULL, 'Strength', 80, 5, 7, FALSE, TRUE, 'chest_fly', 'Middle Fly', 'bench_press, incline_press, push_up', FALSE, 'cable', FALSE, 3, 60, 2, 85, 88, 30, 92),
('908ebc18-a12c-4336-ba72-8982b5d25989', 'Hands Release Push Up', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Triceps","Front Delts"}'::text[], 'The Hands Release Push Up is a pushing exercise that targets your chest muscles. Secondary activation of your triceps, front delts provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. A well-developed chest contributes to upper body strength and aesthetics.', '39471201', '39471201-Hands-Release-Push-up-(female)_Chest_.mp4', 'female', FALSE, '2025-12-03 23:26:33.960339+00', '1. Keep your body in a straight line from head to heels throughout. 2. Lower your chest toward the floor by bending your elbows. 3. Push through your palms to return to the starting position. 4. Complete all reps with control before resting. Keep the movement smooth and controlled. This variation specifically emphasizes the chest.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'push_up', 'Hands Release Push Up', 'bench_press, chest_fly, dip', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('909890c3-197d-49d5-aaa9-2c59382ccee7', 'Standing Straight Arm Chest Fly', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'Target your chest with the Bodyweight Standing Straight Arm Chest Fly, an effective flying movement for upper body strength. You''ll also feel your front delts working to support the movement. The standing position engages your core for stability. A versatile bodyweight movement perfect for home or gym training. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '63081201', '63081201-Bodyweight-Standing-Straight-Arm-Chest-Fly-(female.mp4', 'female', FALSE, '2025-12-03 23:26:31.475486+00', '1. Begin in a standing position with good posture. 2. With a slight bend in your elbows, move the weight in a wide arc. 3. Squeeze your chest muscles at the center/top of the movement. 4. Return with control, feeling the stretch at the bottom. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, 'Standing', NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'chest_fly', 'Standing Straight Arm Chest Fly', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 60, 2, 70, 88, 95, 65),
('909b4708-6c13-4255-b2e3-154cf257c294', 'Glute Bridge Side Tap (Resistance Band)', 'Legs', 'Resistance Band', '{"Glutes"}'::text[], '{"Hamstrings"}'::text[], 'The Resistance Band Glute Bridge Side Tap is a hip-dominant bridging exercise that targets your glutes. Secondary activation of your hamstrings provides additional muscle engagement. Bands are joint-friendly and portable, perfect for any training environment. Strong legs are the foundation for athletic performance and functional fitness.', '90161201', '90161201-Resistance-Band-Glute-Bridge-Side-Tap-(female)_Hip.mp4', 'female', FALSE, '2025-12-03 23:26:36.128549+00', '1. Secure the resistance band appropriately for Resistance Band Glute Bridge Side Tap. 2. Drive through your heels to lift your hips toward the ceiling. 3. Squeeze your glutes hard at the top of the movement. 4. Lower your hips back down with control. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 75, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Side Tap', 'hip_thrust, romanian_deadlift', FALSE, 'band', FALSE, 3, 90, 4, 60, 85, 90, 50),
('90b1d30c-edb8-4b90-89e2-9471c4212856', 'Lying Crunch (Plate)', 'Core', 'Weight Plate', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Weighted Plate Lying Crunch is a core crunching exercise that primarily targets your abs. You''ll also feel your hip flexors working to support the movement. Performing this lying down removes momentum for stricter form. No equipment needed—your body provides all the resistance. Core strength is foundational for athletic performance and injury prevention.', '66031201', '66031201-Weighted-Plate-Lying-Crunch-(male)_Waist_.mp4', 'male', FALSE, '2025-12-03 23:26:30.099411+00', '1. Lie down in the appropriate position for Weighted Plate Lying Crunch. 2. Curl your shoulders off the floor by contracting your abs. 3. Don''t pull on your neck—focus on the abdominal contraction. 4. Lower with control, maintaining some tension. 5. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 5, 7, NULL, 6, 'Lying', NULL, NULL, NULL, 12, 20, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'crunch', 'Weighted Plate Lying Crunch', 'leg_raise, plank, russian_twist, v_up', TRUE, 'plate', FALSE, 3, 60, 2, 70, 88, 95, 65),
('90b73dae-7e7b-4c50-a544-6f13417b3e70', 'Walking On Spot Side Punch', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Elevate your training with this stepping exercise that develops speed, power, and coordination. Secondary activation of your shoulders provides additional muscle engagement. This bodyweight exercise requires no equipment and can be done anywhere. Plyometric training builds explosive power that transfers to sports and daily activities.', '93761201', '93761201-Walking-On-Spot-Side-Punch-(female)_Plyometrics_.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking On Spot Side Punch. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking On Spot Side Punch', 'core_exercise, shoulder_exercise, burpee', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('90bc7011-4920-4d35-aa07-b0d458a3e31d', 'Deep Squat Reach Forward Reach Up', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'Designed to lengthen your quads, the Deep Squat Reach Forward Reach Up helps improve mobility and prevent stiffness. The glutes, hamstrings assist throughout the movement, making this a well-rounded exercise. Regular stretching improves flexibility, reduces injury risk, and aids recovery.', '85741201', '85741201-Deep-Squat-Reach-Forward-Reach-Up-(male)_Stretchin.mp4', 'male', FALSE, '2025-12-03 23:26:28.079801+00', '1. Push your hips back and bend your knees to lower your body. 2. Keep your chest up and knees tracking over your toes. 3. Drive through your heels to stand back up, squeezing your glutes at the top. Engage your stabilizer muscles for better control. Great for building strength in your quads.', 'Squat', NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 85, 7, 8, TRUE, TRUE, 'squat', 'Deep Squat Reach Forward Reach Up', 'leg_press, front_squat, goblet_squat, lunge, leg_extension', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('90c310ad-57e7-4962-a48d-7fef910956b2', 'Double Plank Jack To 4 Mountain Climber', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Shoulders","Lower Back"}'::text[], 'Build power and athleticism with this high-intensity stabilization exercise that challenges your entire body. Secondary activation of your hip flexors, shoulders provides additional muscle engagement. No equipment needed—your body provides all the resistance. Great for improving athletic performance, burning calories, and building conditioning.', '74991201', '74991201-Double-Plank-Jack-to-4-Mountain-Climber-(male)_Ply.mp4', 'male', FALSE, '2025-12-03 23:26:28.52454+00', '1. Hold your body in a straight line from head to heels. 2. Don''t let your hips sag or pike up—engage your core and glutes. 3. Breathe steadily while maintaining the position. 4. Repeat for the prescribed number of repetitions. Keep tension on the target muscles throughout. This exercise is excellent for abs development.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 4, NULL, 8, NULL, NULL, NULL, NULL, 8, 12, NULL, 7, NULL, TRUE, NULL, 'Plyometrics', 70, 9, 8, TRUE, TRUE, 'mountain_climber', 'Double Plank Jack To 4 Mountain Climber', 'crunch, leg_raise, russian_twist, dead_bug', TRUE, 'bodyweight', FALSE, 3, 60, 4, 70, 88, 95, 65),
('90cd9665-e40f-451c-a16b-47d01fffbed2', 'Tree Pose Vrksasana', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{}'::text[], 'Target your full body with this movement stretch that helps restore range of motion. Include this in your routine for better mobility and reduced muscle tension. Works well as both a primary exercise or accessory movement. Consistency with this movement will yield noticeable results.', '9611201', '09611201-Tree-Pose-Vrksasana-(female)_Stretching_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Move into the stretch position for Tree Pose Vrksasana. 2. Ease into the stretch until you feel gentle tension (not pain). 3. Hold for 20-30 seconds, breathing deeply and relaxing into the stretch.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'yoga', 'Tree Pose Vrksasana', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('90d9c709-3a6d-4885-8f87-366b66ccbe1e', 'Power Clean Thruster', 'Full Body', 'Bodyweight', '{"Full Body"}'::text[], '{"Quads","Shoulders"}'::text[], 'The Power Clean Thruster is a compound thrusting exercise that engages your entire body. Your quads, shoulders work as secondary movers, adding to the training stimulus. A versatile bodyweight movement perfect for home or gym training. Full body exercises are time-efficient and build functional, real-world strength.', '106961201', '106961201-Power-Clean-Thruster-(female)_Weightlifting_.mp4', 'female', FALSE, '2025-12-03 23:26:35.801913+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Perform the concentric (lifting) phase explosively with maximum effort. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 5, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'thruster', 'Power Clean Thruster', 'clean, hang_clean, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('90e54289-691d-4145-af37-66a4c37c423e', 'Triceps Dip (bench Leg)', 'Arms', 'Bodyweight', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this dipping exercise for bigger arms. Secondary activation of your triceps, front delts provides additional muscle engagement. Arm strength supports grip, pulling, and pushing in compound movements.', '97361201', '97361201-Triceps-Dip-(bench-leg)-(female)_Upper-Arms_.mp4', 'female', FALSE, '2025-12-03 23:26:39.79101+00', '1. Lower your body by bending your elbows to about 90 degrees. 2. Push back up until your arms are fully extended. 3. Continue for your target rep count, maintaining good form throughout. Keep tension on the target muscles throughout. Ideal for triceps strength and endurance.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'dip', 'Triceps Dip', 'bench_press, tricep_pushdown, push_up', TRUE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('90e9e342-3056-4152-9df5-58c107b725c2', 'Lying Toe Touch - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Strengthen your midsection with this movement movement that works your abs. Your hip flexors work as secondary movers, adding to the training stimulus. The lying position provides back support and helps isolate the target muscles. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '78311201', '78311201-Lying-Alternate-Toe-Touch-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.010404+00', '1. Lie down in the appropriate position for Lying Alternate Toe Touch. 2. Alternate between sides/arms/legs with each repetition. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'toe_touch', 'Lying Toe Touch - Alternating', 'high_knees, butt_kicks, jumping_jack', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('90fbcdf0-9a1c-4928-9e2c-0a2e00ce9f9f', 'Leaning Forward Shrug (Dumbbell)', 'Back', 'Dumbbells', '{"Traps"}'::text[], '{"Upper Back"}'::text[], 'The Dumbbell Leaning Forward Shrug is a shrugging exercise that develops back strength and muscle. The dumbbell variation provides freedom of movement and greater range of motion. Back development is crucial for pulling strength and overall upper body function.', '104571201', '104571201-Dumbbell-Leaning-Forward-Shrug-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:24.831811+00', '1. Select a pair of dumbbells at an appropriate weight for Dumbbell Leaning Forward Shrug. 2. Shrug your shoulders straight up toward your ears. 3. Hold briefly at the top, then lower with control. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 82, 5, 7, FALSE, TRUE, 'shrug', 'Leaning Forward Shrug', 'deadlift, bent_over_row, face_pull', TRUE, 'dumbbell', FALSE, 3, 60, 2, 92, 90, 92, 90),
('90fcb1e5-969b-4872-90b8-0d1714a20f02', 'Seated Lotus Pose Hip Horizontal Rotation Side Be', 'Legs', 'Bodyweight', '{"Hips"}'::text[], '{"Glutes","Hip Flexors"}'::text[], 'The Seated Lotus Pose Hip Horizontal Rotation Side Be provides a deep stretch for your hips, ideal for recovery and mobility work. Your glutes work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Include this in your routine for better mobility and reduced muscle tension.', '88531201', '88531201-Sitting-Lotus-Pose-Hip-Horizontal-Rotation-Side-Be.mp4', 'male', FALSE, '2025-12-03 23:26:21.109351+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Rotate your torso through the movement pattern for Seated Lotus Pose Hip Horizontal Rotation Side Be. 3. Control the rotation in both directions—avoid using momentum.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 1, 1, NULL, 3, NULL, NULL, NULL, NULL, 1, 1, NULL, 1, NULL, TRUE, NULL, 'Stretch', 15, 2, 6, FALSE, TRUE, 'glute_exercise', 'Seated Lotus Pose Hip Horizontal Rotation Side Be', 'stretch_hip, stretch_back, plank', FALSE, 'bodyweight', TRUE, 1, 30, 2, 70, 88, 95, 65),
('9114cc2e-0104-4939-b901-537bbc8dc737', 'Lying Floor Slide', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'The Lying Floor Slide is a movement exercise that develops back strength and muscle. Performing this lying down removes momentum for stricter form. A versatile bodyweight movement perfect for home or gym training. Back development is crucial for pulling strength and overall upper body function.', '75381201', '75381201-Lying-Floor-Slide-(male)_Back_.mp4', 'male', FALSE, '2025-12-03 23:26:21.608253+00', '1. Position yourself on the floor for Lying Floor Slide. 2. Lie down in the appropriate position for Lying Floor Slide. 3. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'general_exercise', 'Lying Floor Slide', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('9120ca04-29b7-42d2-9711-8749f1533760', 'Seated Hip Abduction (Machine)', 'Legs', 'Hip Abduction Machine', '{"Glutes"}'::text[], '{"Hip Abductors"}'::text[], 'Build leg strength with this movement movement focusing on your glute med/abductors. Your glutes work as secondary movers, adding to the training stimulus. The seated position helps isolate the target muscles by removing momentum. Machine exercises are great for isolating muscles and training to failure safely. Lower body strength improves everything from walking to heavy compound lifts.', '36111201', '36111201-Lever-Seated-Hip-Abduction-(female)_Hips.mp4', 'female', FALSE, '2025-12-03 23:26:34.855778+00', '1. Adjust the machine settings (seat height, weight, pads) to fit your body for Lever Seated Hip Abduction. 2. Sit with your back supported, core engaged, feet flat on the floor. 3. Complete all reps with control before resting. Keep the movement smooth and controlled.', NULL, NULL, NULL, NULL, NULL, 1, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, FALSE, NULL, 'Strength', 60, 7, 8, TRUE, TRUE, 'hip_abduction', 'Lever Seated Hip Abduction', 'hip_adduction, glute_bridge, clamshell', TRUE, 'machine', FALSE, 3, 90, 4, 80, 75, 20, 88),
('9144967c-647f-4441-a981-3efd9938c67e', 'Side Lying Side Thigh Push', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this pushing movement focusing on your core. Performing this lying down removes momentum for stricter form. This bodyweight exercise requires no equipment and can be done anywhere. Strong legs are the foundation for athletic performance and functional fitness.', '69721201', '69721201-Side-Lying-Side-Thigh-Push-(female)_Hips_.mp4', 'female', FALSE, '2025-12-03 23:26:37.179953+00', '1. Lie on your side with your body aligned. 2. Set up in the starting position for Side Lying Side Thigh Push. 3. Execute the movement with proper form, focusing on your core. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Lying', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 50, 7, 8, TRUE, TRUE, 'leg_exercise', 'Side Lying Side Thigh Push', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('914c7cd5-fae5-42fe-bae7-54094ebb5b26', 'Glute Bridge Single Arm Chest Press (Dumbbell)', 'Legs', 'Dumbbells', '{"Glutes"}'::text[], '{"Triceps","Front Delts"}'::text[], 'Develop your posterior chain with this pressing movement that emphasizes the glutes. Secondary activation of your hamstrings provides additional muscle engagement. Using dumbbells requires more stabilization than barbell variations. Lower body strength improves everything from walking to heavy compound lifts.', '76511201', '76511201-Dumbbell-Glute-Bridge-Single-Arm-Chest-Press-(male.mp4', 'male', FALSE, '2025-12-03 23:26:21.249384+00', '1. Select an appropriate weight dumbbell and hold it in one hand. 2. Lower the weight toward your chest with control. 3. Press the weight up until your arms are extended (don''t lock elbows). 4. Complete all reps on one side, then switch to the other side. 5. Continue for your target rep count, maintaining good form throughout. Keep your shoulders relaxed and away from your ears.', NULL, NULL, NULL, NULL, NULL, 4, NULL, 7, 8, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 77, 7, 8, TRUE, TRUE, 'glute_bridge', 'Glute Bridge Single Arm Chest Press', 'hip_thrust, romanian_deadlift', FALSE, 'dumbbell', FALSE, 3, 90, 4, 92, 90, 92, 90),
('914f13e6-b2f8-4b3c-b2d8-b67f887f7db2', 'Celebratory Hip Thrust', 'Legs', 'Bodyweight', '{"Glutes"}'::text[], '{"Hamstrings","Core"}'::text[], 'Build a stronger core with the Celebratory Hip Thrust, focusing on your abs. Secondary activation of your hamstrings provides additional muscle engagement. A versatile bodyweight movement perfect for home or gym training. A strong core improves posture, protects your spine, and enhances all other lifts.', '57671201', '57671201-Celebratory-Hip-Thrust-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:32.166461+00', '1. Drive through your heels to lift your hips toward the ceiling. 2. Squeeze your glutes hard at the top of the movement. 3. Lower your hips back down with control. 4. Continue for your target rep count, maintaining good form throughout. Maintain consistent tempo throughout the set.', NULL, NULL, NULL, NULL, NULL, 3, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 70, 7, 8, TRUE, TRUE, 'hip_thrust', 'Celebratory Hip Thrust', 'glute_bridge, romanian_deadlift, leg_curl', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('9151099c-b667-427b-9db9-481bc2861d23', 'Triceps Extension (TRX)', 'Arms', 'TRX', '{"Triceps"}'::text[], '{"Chest","Shoulders"}'::text[], 'Build stronger triceps with this extension exercise for bigger arms. The TRX allows you to adjust difficulty by changing your body angle. Arm strength supports grip, pulling, and pushing in compound movements.', '58761201', '58761201-Suspension-Triceps-Extension-(male)_Upper-Arms_.mp4', 'male', FALSE, '2025-12-03 23:26:29.61214+00', '1. Adjust the TRX/suspension straps to the appropriate length for Suspension Triceps Extension. 2. Extend at the elbow until your arm is straight, squeezing the tricep. 3. Lower with control, keeping your upper arm stationary. 4. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 5, 7, NULL, 6, NULL, NULL, NULL, NULL, 10, 15, NULL, 4, NULL, TRUE, NULL, 'Strength', 70, 5, 7, FALSE, TRUE, 'tricep_extension', 'Suspension Triceps Extension', 'tricep_pushdown, close_grip_bench', FALSE, 'trx', FALSE, 3, 60, 2, 68, 85, 85, 70),
('915eb2ec-f465-4545-9f47-4c03e6d1dce1', 'Walking Front Kick Reach Front', 'Legs', 'Bodyweight', '{"Quads"}'::text[], '{"Glutes","Hamstrings"}'::text[], 'A challenging plyometric exercise, the Walking Front Kick Reach Front builds reactive power and improves conditioning. A versatile bodyweight movement perfect for home or gym training. Plyometric training builds explosive power that transfers to sports and daily activities.', '93681201', '93681201-Walking-Front-Kick-Reach-Front-(female)_Plyometric.mp4', 'female', FALSE, '2025-12-03 23:26:39.91585+00', '1. Set up in the starting position for Walking Front Kick Reach Front. 2. Execute the movement with proper form, focusing on your full body. 3. Control both the lifting and lowering phases of the movement. 4. Complete all reps with control before resting.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 2, 2, NULL, 10, NULL, NULL, NULL, NULL, 1, 1, NULL, 3, NULL, TRUE, NULL, 'Cardio', 50, 9, 8, FALSE, TRUE, 'walking', 'Walking Front Kick Reach Front', 'hip_flexor, lunge, dynamic_warmup', FALSE, 'bodyweight', TRUE, 1, 60, 4, 70, 88, 95, 65),
('9161740a-afdd-4988-bd80-67b2aa0a6213', 'Standing Behind Head Crossover And Back Squeeze', 'Chest', 'Bodyweight', '{"Chest"}'::text[], '{"Front Delts"}'::text[], 'The Standing Behind Head Crossover And Back Squeeze is a movement exercise that targets your chest muscles. The front delts assist throughout the movement, making this a well-rounded exercise. Performing this standing challenges your balance and core engagement. This bodyweight exercise requires no equipment and can be done anywhere. Chest strength improves pushing power for sports, daily tasks, and other lifts.', '95431201', '95431201-Standing-Behind-Head-Crossover-And-Back-Squeeze-(f.mp4', 'female', FALSE, '2025-12-03 23:26:38.425788+00', '1. Stand with feet about shoulder-width apart. 2. Set up in the starting position for Standing Behind Head Crossover And Back Squeeze. 3. Execute the movement with proper form, focusing on your chest. 4. Control both the lifting and lowering phases of the movement. 5. Repeat for the prescribed number of repetitions.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Standing', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'chest_fly', 'Standing Behind Head Crossover And Back Squeeze', 'bench_press, incline_press, push_up', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('917e7c92-4abd-4f2b-8068-3a3dad510463', 'Seated Knee Tuck - Alternating', 'Core', 'Bodyweight', '{"Abs"}'::text[], '{"Hip Flexors"}'::text[], 'Build leg strength with this movement movement focusing on your abs. The hip flexors assist throughout the movement, making this a well-rounded exercise. The seated position helps isolate the target muscles by removing momentum. Strong legs are the foundation for athletic performance and functional fitness.', '88581201', '88581201-Seated-Alternate-Knee-Tuck-(male)_Hips_.mp4', 'male', FALSE, '2025-12-03 23:26:23.466497+00', '1. Sit with your back supported, core engaged, feet flat on the floor. 2. Alternate between sides/arms/legs with each repetition. 3. Continue for your target rep count, maintaining good form throughout. Focus on maintaining proper breathing throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, 'Seated', NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 52, 7, 8, TRUE, TRUE, 'general_exercise', 'Seated Knee Tuck - Alternating', 'squat, leg_extension, lunge', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
('9188b471-7f9c-4140-9025-e660d599ae37', 'Oblique V Up On Floor', 'Core', 'Bodyweight', '{"Obliques"}'::text[], '{"Abs"}'::text[], 'This movement exercise engages your abs for improved core stability and strength. The abs assist throughout the movement, making this a well-rounded exercise. This bodyweight exercise requires no equipment and can be done anywhere. Building core stability helps with everything from heavy deadlifts to daily activities.', '57791201', '57791201-Oblique-V-up-on-Floor-(female)_Waist_.mp4', 'female', FALSE, '2025-12-03 23:26:35.532804+00', '1. Position yourself on the floor for Oblique V Up On Floor. 2. Set up in the starting position for Oblique V Up On Floor. 3. Execute the movement with proper form, focusing on your abs. 4. Control both the lifting and lowering phases of the movement. 5. Continue for your target rep count, maintaining good form throughout.', NULL, NULL, NULL, NULL, NULL, 2, NULL, 7, 7, NULL, 5, NULL, NULL, NULL, NULL, 8, 12, NULL, 6, NULL, TRUE, NULL, 'Strength', 45, 7, 8, TRUE, TRUE, 'v_up', 'Oblique V Up On Floor', 'squat, bench_press, deadlift', FALSE, 'bodyweight', FALSE, 3, 90, 4, 70, 88, 95, 65),
